/// Represents the current authorization state of the TDLib client
sealed class AuthorizationState extends TdObject {
  const AuthorizationState();

  static AuthorizationState fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'authorizationStateWaitTdlibParameters' =>
          AuthorizationStateWaitTdlibParameters.fromJson(json),
        'authorizationStateWaitPhoneNumber' =>
          AuthorizationStateWaitPhoneNumber.fromJson(json),
        'authorizationStateWaitPremiumPurchase' =>
          AuthorizationStateWaitPremiumPurchase.fromJson(json),
        'authorizationStateWaitEmailAddress' =>
          AuthorizationStateWaitEmailAddress.fromJson(json),
        'authorizationStateWaitEmailCode' =>
          AuthorizationStateWaitEmailCode.fromJson(json),
        'authorizationStateWaitCode' => AuthorizationStateWaitCode.fromJson(
          json,
        ),
        'authorizationStateWaitOtherDeviceConfirmation' =>
          AuthorizationStateWaitOtherDeviceConfirmation.fromJson(json),
        'authorizationStateWaitRegistration' =>
          AuthorizationStateWaitRegistration.fromJson(json),
        'authorizationStateWaitPassword' =>
          AuthorizationStateWaitPassword.fromJson(json),
        'authorizationStateReady' => AuthorizationStateReady.fromJson(json),
        'authorizationStateLoggingOut' => AuthorizationStateLoggingOut.fromJson(
          json,
        ),
        'authorizationStateClosing' => AuthorizationStateClosing.fromJson(json),
        'authorizationStateClosed' => AuthorizationStateClosed.fromJson(json),
        final t => throw ArgumentError(
          'unknown AuthorizationState constructor: $t',
        ),
      };
}

