/// Represents a local file
final class LocalFile extends TdObject {
  /// Local path to the locally available file part; may be empty
  final String path;

  /// True, if it is possible to download or generate the file
  final bool canBeDownloaded;

  /// True, if the file can be deleted
  final bool canBeDeleted;

  /// True, if the file is currently being downloaded (or a local copy is being generated by some other means)
  final bool isDownloadingActive;

  /// True, if the local copy is fully available
  final bool isDownloadingCompleted;

  /// Download will be started from this offset. downloaded_prefix_size is calculated from this offset
  final int downloadOffset;

  /// If is_downloading_completed is false, then only some prefix of the file starting from download_offset is ready to be read. downloaded_prefix_size is the size of that prefix in bytes
  final int downloadedPrefixSize;

  /// Total downloaded file size, in bytes. Can be used only for calculating download progress. The actual file size may be bigger, and some parts of it may contain garbage
  final int downloadedSize;

  const LocalFile({
    required this.path,
    required this.canBeDownloaded,
    required this.canBeDeleted,
    required this.isDownloadingActive,
    required this.isDownloadingCompleted,
    required this.downloadOffset,
    required this.downloadedPrefixSize,
    required this.downloadedSize,
  });

  static const String constructorType = 'localFile';
  @override
  String get tdType => constructorType;

  factory LocalFile.fromJson(Map<String, Object?> json) => LocalFile(
    path: ((json['path'] as String?) ?? ''),
    canBeDownloaded: ((json['can_be_downloaded'] as bool?) ?? false),
    canBeDeleted: ((json['can_be_deleted'] as bool?) ?? false),
    isDownloadingActive: ((json['is_downloading_active'] as bool?) ?? false),
    isDownloadingCompleted:
        ((json['is_downloading_completed'] as bool?) ?? false),
    downloadOffset: ((json['download_offset'] as num?) ?? 0).toInt(),
    downloadedPrefixSize: ((json['downloaded_prefix_size'] as num?) ?? 0)
        .toInt(),
    downloadedSize: ((json['downloaded_size'] as num?) ?? 0).toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'path': path,
    'can_be_downloaded': canBeDownloaded,
    'can_be_deleted': canBeDeleted,
    'is_downloading_active': isDownloadingActive,
    'is_downloading_completed': isDownloadingCompleted,
    'download_offset': downloadOffset,
    'downloaded_prefix_size': downloadedPrefixSize,
    'downloaded_size': downloadedSize,
  };
}

/// Represents a remote file
final class RemoteFile extends TdObject {
  /// Remote file identifier; may be empty. Can be used by the current user across application restarts or even from other devices. Uniquely identifies a file, but a file can have a lot of different valid identifiers. If the identifier starts with "http://" or "https://", it represents the HTTP URL of the file. TDLib is currently unable to download files if only their URL is known. If downloadFile/addFileToDownloads is called on such a file or if it is sent to a secret chat, TDLib starts a file generation process by sending updateFileGenerationStart to the application with the HTTP URL in the original_path and "#url#" as the conversion string. Application must generate the file by downloading it to the specified location
  final String id;

  /// Unique file identifier; may be empty if unknown. The unique file identifier which is the same for the same file even for different users and is persistent over time
  final String uniqueId;

  /// True, if the file is currently being uploaded (or a remote copy is being generated by some other means)
  final bool isUploadingActive;

  /// True, if a remote copy is fully available
  final bool isUploadingCompleted;

  /// Size of the remote available part of the file, in bytes; 0 if unknown
  final int uploadedSize;

  const RemoteFile({
    required this.id,
    required this.uniqueId,
    required this.isUploadingActive,
    required this.isUploadingCompleted,
    required this.uploadedSize,
  });

  static const String constructorType = 'remoteFile';
  @override
  String get tdType => constructorType;

  factory RemoteFile.fromJson(Map<String, Object?> json) => RemoteFile(
    id: ((json['id'] as String?) ?? ''),
    uniqueId: ((json['unique_id'] as String?) ?? ''),
    isUploadingActive: ((json['is_uploading_active'] as bool?) ?? false),
    isUploadingCompleted: ((json['is_uploading_completed'] as bool?) ?? false),
    uploadedSize: ((json['uploaded_size'] as num?) ?? 0).toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id,
    'unique_id': uniqueId,
    'is_uploading_active': isUploadingActive,
    'is_uploading_completed': isUploadingCompleted,
    'uploaded_size': uploadedSize,
  };
}

/// Represents a file
final class File extends TdObject {
  /// Unique file identifier
  final int id;

  /// File size, in bytes; 0 if unknown
  final int size;

