  final int expectedSize;

  /// Information about the local copy of the file
  final LocalFile? local;

  /// Information about the remote copy of the file
  final RemoteFile? remote;

  const File({
    required this.id,
    required this.size,
    required this.expectedSize,
    this.local,
    this.remote,
  });

  static const String constructorType = 'file';
  @override
  String get tdType => constructorType;

  factory File.fromJson(Map<String, Object?> json) => File(
    id: ((json['id'] as num?) ?? 0).toInt(),
    size: ((json['size'] as num?) ?? 0).toInt(),
    expectedSize: ((json['expected_size'] as num?) ?? 0).toInt(),
    local: json['local'] == null
        ? null
        : LocalFile.fromJson(json['local'] as Map<String, Object?>),
    remote: json['remote'] == null
        ? null
        : RemoteFile.fromJson(json['remote'] as Map<String, Object?>),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id,
    'size': size,
    'expected_size': expectedSize,
    'local': local?.toJson(),
    'remote': remote?.toJson(),
  };
}

