/// Describes a game. Use getInternalLink with internalLinkTypeGame to share the game
final class Game extends TdObject {
  /// Unique game identifier
  final int id;

  /// Game short name
  final String shortName;

  /// Game title
  final String title;

  /// Game text, usually containing scoreboards for a game
  final FormattedText? text;

  /// Game description
  final String description;

  /// Game photo
  final Photo? photo;

  /// Game animation; may be null
  final Animation? animation;

  const Game({
    required this.id,
    required this.shortName,
    required this.title,
    this.text,
    required this.description,
    this.photo,
    this.animation,
  });

  static const String constructorType = 'game';
  @override
  String get tdType => constructorType;

  factory Game.fromJson(Map<String, Object?> json) => Game(
    id: int.parse((json['id'] as String?) ?? '0'),
    shortName: ((json['short_name'] as String?) ?? ''),
    title: ((json['title'] as String?) ?? ''),
    text: json['text'] == null
        ? null
        : FormattedText.fromJson(json['text'] as Map<String, Object?>),
    description: ((json['description'] as String?) ?? ''),
    photo: json['photo'] == null
        ? null
        : Photo.fromJson(json['photo'] as Map<String, Object?>),
    animation: json['animation'] == null
        ? null
        : Animation.fromJson(json['animation'] as Map<String, Object?>),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id.toString(),
    'short_name': shortName,
    'title': title,
    'text': text?.toJson(),
    'description': description,
    'photo': photo?.toJson(),
    'animation': animation?.toJson(),
  };
}

/// Describes state of the stake dice
final class StakeDiceState extends TdObject {
  /// Hash of the state to use for sending the next dice; may be empty if the stake dice can't be sent by the current user
  final String stateHash;

  /// The amount of TON Grams staked in the previous roll; in the smallest units of the currency
  final int stakeGramAmount;

  /// The amounts of Grams that are suggested to be staked; in the smallest units of the currency
  final List<int> suggestedStakeGramAmounts;

  /// The number of rolled sixes towards the streak; 0-2
  final int currentStreak;

  /// The number of Grams received by the user for each 1000 Grams staked if the dice outcome is 1-6 correspondingly; may be empty if the stake dice can't be sent by the current user
  final List<int> prizePerMille;

  /// The number of Grams received by the user for each 1000 Grams staked if the dice outcome is 6 three times in a row with the same stake
  final int streakPrizePerMille;

  const StakeDiceState({
    required this.stateHash,
    required this.stakeGramAmount,
    required this.suggestedStakeGramAmounts,
    required this.currentStreak,
    required this.prizePerMille,
    required this.streakPrizePerMille,
  });

  static const String constructorType = 'stakeDiceState';
  @override
  String get tdType => constructorType;

  factory StakeDiceState.fromJson(Map<String, Object?> json) => StakeDiceState(
    stateHash: ((json['state_hash'] as String?) ?? ''),
    stakeGramAmount: ((json['stake_gram_amount'] as num?) ?? 0).toInt(),
    suggestedStakeGramAmounts:
        ((json['suggested_stake_gram_amounts'] as List?) ?? const [])
            .map((e) => ((e as num?) ?? 0).toInt())
            .toList(),
    currentStreak: ((json['current_streak'] as num?) ?? 0).toInt(),
    prizePerMille: ((json['prize_per_mille'] as List?) ?? const [])
        .map((e) => ((e as num?) ?? 0).toInt())
        .toList(),
    streakPrizePerMille: ((json['streak_prize_per_mille'] as num?) ?? 0)
        .toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'state_hash': stateHash,
    'stake_gram_amount': stakeGramAmount,
    'suggested_stake_gram_amounts': suggestedStakeGramAmounts
        .map((e) => e)
        .toList(),
    'current_streak': currentStreak,
    'prize_per_mille': prizePerMille.map((e) => e).toList(),
    'streak_prize_per_mille': streakPrizePerMille,
  };
}

