/// Describes a poll
final class Poll extends TdObject {
  /// Unique poll identifier
  final int id;

  /// Poll question; 1-300 characters; may contain only custom emoji entities
  final FormattedText? question;

  /// List of poll answer options
  final List<PollOption> options;

  /// Total number of voters, participating in the poll
  final int totalVoterCount;

  /// Identifiers of recent voters, if the poll is non-anonymous and poll results are available
  final List<MessageSender> recentVoterIds;

  /// True, if the current user can get voters in the poll using getPollVoters
  final bool canGetVoters;

  /// True, if the current user can see results of the poll
  final bool canSeeResults;

  /// True, if the poll is anonymous
  final bool isAnonymous;

  /// True, if multiple answer options can be chosen simultaneously
  final bool allowsMultipleAnswers;

  /// True, if the poll can be answered multiple times
  final bool allowsRevoting;

  /// True, if only the users that are members of the chat for more than a day will be able to vote
  final bool membersOnly;

  /// The list of two-letter ISO 3166-1 alpha-2 codes of countries, users from which will be able to vote. If empty, then all users can participate in the poll
  final List<String> countryCodes;

  /// The list of 0-based poll identifiers in which the options of the poll must be shown; empty if the order of options must not be changed
  final List<int> optionOrder;

  /// Type of the poll
  final PollType? type;

  /// Amount of time the poll will be active after creation, in seconds
  final int openPeriod;

  /// Point in time (Unix timestamp) when the poll will automatically be closed
  final int closeDate;

  /// True, if the poll is closed
  final bool isClosed;

  /// The reason describing, why the current user can't vote in the poll; may be null if the user can vote in the poll
  final PollVoteRestrictionReason? voteRestrictionReason;

  const Poll({
    required this.id,
    this.question,
    required this.options,
    required this.totalVoterCount,
    required this.recentVoterIds,
    required this.canGetVoters,
    required this.canSeeResults,
    required this.isAnonymous,
    required this.allowsMultipleAnswers,
    required this.allowsRevoting,
    required this.membersOnly,
    required this.countryCodes,
    required this.optionOrder,
    this.type,
    required this.openPeriod,
    required this.closeDate,
    required this.isClosed,
    this.voteRestrictionReason,
  });

  static const String constructorType = 'poll';
  @override
  String get tdType => constructorType;

  factory Poll.fromJson(Map<String, Object?> json) => Poll(
    id: int.parse((json['id'] as String?) ?? '0'),
    question: json['question'] == null
        ? null
        : FormattedText.fromJson(json['question'] as Map<String, Object?>),
    options: ((json['options'] as List?) ?? const [])
        .map((e) => PollOption.fromJson(e as Map<String, Object?>))
        .toList(),
    totalVoterCount: ((json['total_voter_count'] as num?) ?? 0).toInt(),
    recentVoterIds: ((json['recent_voter_ids'] as List?) ?? const [])
        .map((e) => MessageSender.fromJson(e as Map<String, Object?>))
        .toList(),
    canGetVoters: ((json['can_get_voters'] as bool?) ?? false),
    canSeeResults: ((json['can_see_results'] as bool?) ?? false),
    isAnonymous: ((json['is_anonymous'] as bool?) ?? false),
    allowsMultipleAnswers:
        ((json['allows_multiple_answers'] as bool?) ?? false),
    allowsRevoting: ((json['allows_revoting'] as bool?) ?? false),
    membersOnly: ((json['members_only'] as bool?) ?? false),
    countryCodes: ((json['country_codes'] as List?) ?? const [])
        .map((e) => ((e as String?) ?? ''))
        .toList(),
    optionOrder: ((json['option_order'] as List?) ?? const [])
        .map((e) => ((e as num?) ?? 0).toInt())
        .toList(),
    type: json['type'] == null
        ? null
        : PollType.fromJson(json['type'] as Map<String, Object?>),
    openPeriod: ((json['open_period'] as num?) ?? 0).toInt(),
    closeDate: ((json['close_date'] as num?) ?? 0).toInt(),
    isClosed: ((json['is_closed'] as bool?) ?? false),
    voteRestrictionReason: json['vote_restriction_reason'] == null
        ? null
        : PollVoteRestrictionReason.fromJson(
            json['vote_restriction_reason'] as Map<String, Object?>,
          ),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id.toString(),
    'question': question?.toJson(),
    'options': options.map((e) => e.toJson()).toList(),
    'total_voter_count': totalVoterCount,
    'recent_voter_ids': recentVoterIds.map((e) => e.toJson()).toList(),
    'can_get_voters': canGetVoters,
    'can_see_results': canSeeResults,
    'is_anonymous': isAnonymous,
    'allows_multiple_answers': allowsMultipleAnswers,
    'allows_revoting': allowsRevoting,
    'members_only': membersOnly,
    'country_codes': countryCodes.map((e) => e).toList(),
    'option_order': optionOrder.map((e) => e).toList(),
    'type': type?.toJson(),
    'open_period': openPeriod,
    'close_date': closeDate,
    'is_closed': isClosed,
    'vote_restriction_reason': voteRestrictionReason?.toJson(),
  };
}

/// Describes an alternative re-encoded quality of a video file
final class AlternativeVideo extends TdObject {
  /// Unique identifier of the alternative video, which is used in the HLS file
  final int id;

  /// Video width
  final int width;

  /// Video height
  final int height;

  /// Codec used for video file encoding, for example, "h264", "h265", "av1", or "av01"
  final String codec;

  /// HLS file describing the video
  final File? hlsFile;

  /// File containing the video
  final File? video;

  const AlternativeVideo({
    required this.id,
    required this.width,
    required this.height,
    required this.codec,
    this.hlsFile,
    this.video,
  });

  static const String constructorType = 'alternativeVideo';
  @override
  String get tdType => constructorType;

  factory AlternativeVideo.fromJson(Map<String, Object?> json) =>
      AlternativeVideo(
        id: int.parse((json['id'] as String?) ?? '0'),
        width: ((json['width'] as num?) ?? 0).toInt(),
        height: ((json['height'] as num?) ?? 0).toInt(),
        codec: ((json['codec'] as String?) ?? ''),
        hlsFile: json['hls_file'] == null
            ? null
            : File.fromJson(json['hls_file'] as Map<String, Object?>),
        video: json['video'] == null
            ? null
            : File.fromJson(json['video'] as Map<String, Object?>),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id.toString(),
    'width': width,
    'height': height,
    'codec': codec,
    'hls_file': hlsFile?.toJson(),
    'video': video?.toJson(),
  };
}

