  /// True, if the background is dark and is recommended to be used with dark theme
  final bool isDark;

  /// Unique background name
  final String name;

  /// Document with the background; may be null. Null only for filled and chat theme backgrounds
  final Document? document;

  /// Type of the background
  final BackgroundType? type;

  const Background({
    required this.id,
    required this.isDefault,
    required this.isDark,
    required this.name,
    this.document,
    this.type,
  });

  static const String constructorType = 'background';
  @override
  String get tdType => constructorType;

  factory Background.fromJson(Map<String, Object?> json) => Background(
    id: int.parse((json['id'] as String?) ?? '0'),
    isDefault: ((json['is_default'] as bool?) ?? false),
    isDark: ((json['is_dark'] as bool?) ?? false),
    name: ((json['name'] as String?) ?? ''),
    document: json['document'] == null
        ? null
        : Document.fromJson(json['document'] as Map<String, Object?>),
    type: json['type'] == null
        ? null
        : BackgroundType.fromJson(json['type'] as Map<String, Object?>),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id.toString(),
    'is_default': isDefault,
    'is_dark': isDark,
    'name': name,
    'document': document?.toJson(),
    'type': type?.toJson(),
  };
}

