/// Describes a user profile photo
final class ProfilePhoto extends TdObject {
  /// Photo identifier; 0 for an empty photo. Can be used to find a photo in a list of user profile photos
  final int id;

  /// A small (160x160) user profile photo. The file can be downloaded only before the photo is changed
  final File? small;

  /// A big (640x640) user profile photo. The file can be downloaded only before the photo is changed
  final File? big;

  /// User profile photo minithumbnail; may be null
  final Minithumbnail? minithumbnail;

  /// True, if the photo has animated variant
  final bool hasAnimation;

  /// True, if the photo is visible only for the current user
  final bool isPersonal;

  const ProfilePhoto({
    required this.id,
    this.small,
    this.big,
    this.minithumbnail,
    required this.hasAnimation,
    required this.isPersonal,
  });

  static const String constructorType = 'profilePhoto';
  @override
  String get tdType => constructorType;

  factory ProfilePhoto.fromJson(Map<String, Object?> json) => ProfilePhoto(
    id: int.parse((json['id'] as String?) ?? '0'),
    small: json['small'] == null
        ? null
        : File.fromJson(json['small'] as Map<String, Object?>),
    big: json['big'] == null
        ? null
        : File.fromJson(json['big'] as Map<String, Object?>),
    minithumbnail: json['minithumbnail'] == null
        ? null
        : Minithumbnail.fromJson(json['minithumbnail'] as Map<String, Object?>),
    hasAnimation: ((json['has_animation'] as bool?) ?? false),
    isPersonal: ((json['is_personal'] as bool?) ?? false),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id.toString(),
    'small': small?.toJson(),
    'big': big?.toJson(),
    'minithumbnail': minithumbnail?.toJson(),
    'has_animation': hasAnimation,
    'is_personal': isPersonal,
  };
}

