/// Describes a tab shown in a user or a chat profile
sealed class ProfileTab extends TdObject {
  const ProfileTab();

  static ProfileTab fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'profileTabPosts' => ProfileTabPosts.fromJson(json),
        'profileTabGifts' => ProfileTabGifts.fromJson(json),
        'profileTabMedia' => ProfileTabMedia.fromJson(json),
        'profileTabFiles' => ProfileTabFiles.fromJson(json),
        'profileTabLinks' => ProfileTabLinks.fromJson(json),
        'profileTabMusic' => ProfileTabMusic.fromJson(json),
        'profileTabVoice' => ProfileTabVoice.fromJson(json),
        'profileTabGifs' => ProfileTabGifs.fromJson(json),
        final t => throw ArgumentError('unknown ProfileTab constructor: $t'),
      };
}

