/// Represents the type of user. The following types are possible: regular users, deleted users and bots
sealed class UserType extends TdObject {
  const UserType();

  static UserType fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'userTypeRegular' => UserTypeRegular.fromJson(json),
        'userTypeDeleted' => UserTypeDeleted.fromJson(json),
        'userTypeBot' => UserTypeBot.fromJson(json),
        'userTypeUnknown' => UserTypeUnknown.fromJson(json),
        final t => throw ArgumentError('unknown UserType constructor: $t'),
      };
}

/// A regular user
final class UserTypeRegular extends UserType {
  const UserTypeRegular();

  static const String constructorType = 'userTypeRegular';
  @override
  String get tdType => constructorType;

  factory UserTypeRegular.fromJson(Map<String, Object?> json) =>
      UserTypeRegular();

  @override
  Map<String, Object?> toJson() => {'@type': constructorType};
}

