/// Describes conditions for sending of away messages by a Telegram Business account
sealed class BusinessAwayMessageSchedule extends TdObject {
  const BusinessAwayMessageSchedule();

  static BusinessAwayMessageSchedule fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'businessAwayMessageScheduleAlways' =>
          BusinessAwayMessageScheduleAlways.fromJson(json),
        'businessAwayMessageScheduleOutsideOfOpeningHours' =>
          BusinessAwayMessageScheduleOutsideOfOpeningHours.fromJson(json),
        'businessAwayMessageScheduleCustom' =>
          BusinessAwayMessageScheduleCustom.fromJson(json),
        final t => throw ArgumentError(
          'unknown BusinessAwayMessageSchedule constructor: $t',
        ),
      };
}

/// Send away messages always
final class BusinessAwayMessageScheduleAlways
    extends BusinessAwayMessageSchedule {
  const BusinessAwayMessageScheduleAlways();

  static const String constructorType = 'businessAwayMessageScheduleAlways';
  @override
  String get tdType => constructorType;

  factory BusinessAwayMessageScheduleAlways.fromJson(
    Map<String, Object?> json,
  ) => BusinessAwayMessageScheduleAlways();

  @override
  Map<String, Object?> toJson() => {'@type': constructorType};
}

/// Send away messages outside of the business opening hours
final class BusinessAwayMessageScheduleOutsideOfOpeningHours
