/// Describes private chats chosen for automatic interaction with a business
final class BusinessRecipients extends TdObject {
  /// Identifiers of selected private chats
  final List<int> chatIds;

  /// Identifiers of private chats that are always excluded; for businessConnectedBot only
  final List<int> excludedChatIds;

  /// True, if all existing private chats are selected
  final bool selectExistingChats;

  /// True, if all new private chats are selected
  final bool selectNewChats;

  /// True, if all private chats with contacts are selected
  final bool selectContacts;

  /// True, if all private chats with non-contacts are selected
  final bool selectNonContacts;

  /// If true, then all private chats except the selected are chosen. Otherwise, only the selected chats are chosen
  final bool excludeSelected;

  const BusinessRecipients({
    required this.chatIds,
    required this.excludedChatIds,
    required this.selectExistingChats,
    required this.selectNewChats,
    required this.selectContacts,
    required this.selectNonContacts,
    required this.excludeSelected,
  });

  static const String constructorType = 'businessRecipients';
  @override
  String get tdType => constructorType;

  factory BusinessRecipients.fromJson(Map<String, Object?> json) =>
      BusinessRecipients(
        chatIds: ((json['chat_ids'] as List?) ?? const [])
            .map((e) => ((e as num?) ?? 0).toInt())
            .toList(),
        excludedChatIds: ((json['excluded_chat_ids'] as List?) ?? const [])
            .map((e) => ((e as num?) ?? 0).toInt())
            .toList(),
        selectExistingChats:
            ((json['select_existing_chats'] as bool?) ?? false),
        selectNewChats: ((json['select_new_chats'] as bool?) ?? false),
        selectContacts: ((json['select_contacts'] as bool?) ?? false),
        selectNonContacts: ((json['select_non_contacts'] as bool?) ?? false),
        excludeSelected: ((json['exclude_selected'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'chat_ids': chatIds.map((e) => e).toList(),
    'excluded_chat_ids': excludedChatIds.map((e) => e).toList(),
    'select_existing_chats': selectExistingChats,
    'select_new_chats': selectNewChats,
    'select_contacts': selectContacts,
    'select_non_contacts': selectNonContacts,
    'exclude_selected': excludeSelected,
  };
}

/// Describes settings for messages that are automatically sent by a Telegram Business account when it is away
final class BusinessAwayMessageSettings extends TdObject {
  /// Unique quick reply shortcut identifier for the away messages
  final int shortcutId;

  /// Chosen recipients of the away messages
  final BusinessRecipients? recipients;

  /// Settings used to check whether the current user is away
  final BusinessAwayMessageSchedule? schedule;

  /// True, if the messages must not be sent if the account was online in the last 10 minutes
  final bool offlineOnly;

  const BusinessAwayMessageSettings({
    required this.shortcutId,
    this.recipients,
    this.schedule,
    required this.offlineOnly,
  });

  static const String constructorType = 'businessAwayMessageSettings';
  @override
  String get tdType => constructorType;

  factory BusinessAwayMessageSettings.fromJson(Map<String, Object?> json) =>
      BusinessAwayMessageSettings(
        shortcutId: ((json['shortcut_id'] as num?) ?? 0).toInt(),
        recipients: json['recipients'] == null
            ? null
            : BusinessRecipients.fromJson(
                json['recipients'] as Map<String, Object?>,
              ),
        schedule: json['schedule'] == null
            ? null
            : BusinessAwayMessageSchedule.fromJson(
                json['schedule'] as Map<String, Object?>,
              ),
        offlineOnly: ((json['offline_only'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'shortcut_id': shortcutId,
    'recipients': recipients?.toJson(),
    'schedule': schedule?.toJson(),
    'offline_only': offlineOnly,
  };
}

