  factory SuggestedPostInfo.fromJson(
    Map<String, Object?> json,
  ) => SuggestedPostInfo(
    price: json['price'] == null
        ? null
        : SuggestedPostPrice.fromJson(json['price'] as Map<String, Object?>),
    sendDate: ((json['send_date'] as num?) ?? 0).toInt(),
    state: json['state'] == null
        ? null
        : SuggestedPostState.fromJson(json['state'] as Map<String, Object?>),
    canBeApproved: ((json['can_be_approved'] as bool?) ?? false),
    canBeDeclined: ((json['can_be_declined'] as bool?) ?? false),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'price': price?.toJson(),
    'send_date': sendDate,
    'state': state?.toJson(),
    'can_be_approved': canBeApproved,
    'can_be_declined': canBeDeclined,
  };
}

