/// Describes a gift that can be sent to another user or channel chat
final class Gift extends TdObject {
  /// Unique identifier of the gift
  final int id;

  /// Identifier of the chat that published the gift; 0 if none
  final int publisherChatId;

  /// The sticker representing the gift
  final Sticker? sticker;

  /// Number of Telegram Stars that must be paid for the gift
  final int starCount;

  /// Number of Telegram Stars that can be claimed by the receiver instead of the regular gift by default. If the gift was paid with just bought Telegram Stars, then full value can be claimed
  final int defaultSellStarCount;

  /// Number of Telegram Stars that must be paid to upgrade the gift; 0 if upgrade isn't possible
  final int upgradeStarCount;

  /// Number of unique gift variants that are available for the upgraded gift; 0 if unknown
  final int upgradeVariantCount;

  /// True, if the gift can be used to customize the user's name, and backgrounds of profile photo, reply header, and link preview
  final bool hasColors;

  /// True, if the gift is a birthday gift
  final bool isForBirthday;

  /// True, if the gift can be bought only by Telegram Premium subscribers
  final bool isPremium;

  /// Information about the auction on which the gift can be purchased; may be null if the gift can be purchased directly
  final GiftAuction? auctionInfo;

  /// Point in time (Unix timestamp) when the gift can be sent next time by the current user; may be 0 or a date in the past. If the date is in the future, then call canSendGift to get the reason, why the gift can't be sent now
  final int nextSendDate;

  /// Number of times the gift can be purchased by the current user; may be null if not limited
  final GiftPurchaseLimits? userLimits;

  /// Number of times the gift can be purchased by all users; may be null if not limited
  final GiftPurchaseLimits? overallLimits;

  /// Background of the gift
  final GiftBackground? background;

  /// Point in time (Unix timestamp) when the gift was sent for the first time; for sold out gifts only
  final int firstSendDate;

  /// Point in time (Unix timestamp) when the gift was sent for the last time; for sold out gifts only
  final int lastSendDate;

  const Gift({
    required this.id,
    required this.publisherChatId,
    this.sticker,
    required this.starCount,
    required this.defaultSellStarCount,
    required this.upgradeStarCount,
    required this.upgradeVariantCount,
    required this.hasColors,
    required this.isForBirthday,
    required this.isPremium,
    this.auctionInfo,
    required this.nextSendDate,
    this.userLimits,
    this.overallLimits,
    this.background,
    required this.firstSendDate,
    required this.lastSendDate,
  });

  static const String constructorType = 'gift';
  @override
  String get tdType => constructorType;

  factory Gift.fromJson(Map<String, Object?> json) => Gift(
    id: int.parse((json['id'] as String?) ?? '0'),
    publisherChatId: ((json['publisher_chat_id'] as num?) ?? 0).toInt(),
    sticker: json['sticker'] == null
        ? null
        : Sticker.fromJson(json['sticker'] as Map<String, Object?>),
    starCount: ((json['star_count'] as num?) ?? 0).toInt(),
    defaultSellStarCount: ((json['default_sell_star_count'] as num?) ?? 0)
        .toInt(),
    upgradeStarCount: ((json['upgrade_star_count'] as num?) ?? 0).toInt(),
    upgradeVariantCount: ((json['upgrade_variant_count'] as num?) ?? 0).toInt(),
    hasColors: ((json['has_colors'] as bool?) ?? false),
    isForBirthday: ((json['is_for_birthday'] as bool?) ?? false),
    isPremium: ((json['is_premium'] as bool?) ?? false),
    auctionInfo: json['auction_info'] == null
        ? null
        : GiftAuction.fromJson(json['auction_info'] as Map<String, Object?>),
    nextSendDate: ((json['next_send_date'] as num?) ?? 0).toInt(),
    userLimits: json['user_limits'] == null
        ? null
        : GiftPurchaseLimits.fromJson(
            json['user_limits'] as Map<String, Object?>,
          ),
    overallLimits: json['overall_limits'] == null
        ? null
        : GiftPurchaseLimits.fromJson(
            json['overall_limits'] as Map<String, Object?>,
          ),
    background: json['background'] == null
        ? null
        : GiftBackground.fromJson(json['background'] as Map<String, Object?>),
    firstSendDate: ((json['first_send_date'] as num?) ?? 0).toInt(),
    lastSendDate: ((json['last_send_date'] as num?) ?? 0).toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id.toString(),
    'publisher_chat_id': publisherChatId,
    'sticker': sticker?.toJson(),
    'star_count': starCount,
    'default_sell_star_count': defaultSellStarCount,
    'upgrade_star_count': upgradeStarCount,
    'upgrade_variant_count': upgradeVariantCount,
    'has_colors': hasColors,
    'is_for_birthday': isForBirthday,
    'is_premium': isPremium,
    'auction_info': auctionInfo?.toJson(),
    'next_send_date': nextSendDate,
    'user_limits': userLimits?.toJson(),
    'overall_limits': overallLimits?.toJson(),
    'background': background?.toJson(),
    'first_send_date': firstSendDate,
    'last_send_date': lastSendDate,
  };
}

/// Describes an upgraded gift that can be transferred to another owner or transferred to the TON blockchain as an NFT
final class UpgradedGift extends TdObject {
  /// Unique identifier of the gift
  final int id;

  /// Unique identifier of the regular gift from which the gift was upgraded; may be 0 for short period of time for old gifts from database
  final int regularGiftId;

  /// Identifier of the chat that published the gift; 0 if none
  final int publisherChatId;

  /// The title of the upgraded gift
  final String title;

  /// Unique name of the upgraded gift that can be used with internalLinkTypeUpgradedGift or sendResoldGift
  final String name;

  /// Unique number of the upgraded gift among gifts upgraded from the same gift
  final int number;

  /// Total number of gifts that were upgraded from the same gift
  final int totalUpgradedCount;

  /// The maximum number of gifts that can be upgraded from the same gift
  final int maxUpgradedCount;

  /// True, if the gift was used to craft another gift
  final bool isBurned;

  /// True, if the gift was crafted from other gifts
  final bool isCrafted;

  /// True, if the original gift could have been bought only by Telegram Premium subscribers
  final bool isPremium;

  /// True, if the gift can be used to set a theme in a chat
  final bool isThemeAvailable;

  /// Identifier of the chat for which the gift is used to set a theme; 0 if none or the gift isn't owned by the current user
  final int usedThemeChatId;

  /// Identifier of the user or the chat to which the upgraded gift was assigned from blockchain; may be null if none or unknown
  final MessageSender? hostId;

  /// Identifier of the user or the chat that owns the upgraded gift; may be null if none or unknown
  final MessageSender? ownerId;

  /// Address of the gift NFT owner in TON blockchain; may be empty if none. Append the address to getOption("ton_blockchain_explorer_url") to get a link with information about the address
  final String ownerAddress;

  /// Name of the owner for the case when owner identifier and address aren't known
  final String ownerName;

  /// Address of the gift NFT in TON blockchain; may be empty if none. Append the address to getOption("ton_blockchain_explorer_url") to get a link with information about the address
  final String giftAddress;

  /// Model of the upgraded gift
  final UpgradedGiftModel? model;

  /// Symbol of the upgraded gift
  final UpgradedGiftSymbol? symbol;

  /// Backdrop of the upgraded gift
  final UpgradedGiftBackdrop? backdrop;

  /// Information about the originally sent gift; may be null if unknown
  final UpgradedGiftOriginalDetails? originalDetails;

  /// Colors that can be set for user's name, background of empty chat photo, replies to messages and link previews; may be null if none or unknown
  final UpgradedGiftColors? colors;

  /// Resale parameters of the gift; may be null if resale isn't possible
  final GiftResaleParameters? resaleParameters;

  /// True, if an offer to purchase the gift can be sent using sendGiftPurchaseOffer
  final bool canSendPurchaseOffer;

  /// Probability that the gift adds to the chance of successful crafting of a new gift; 0 if the gift can't be used for crafting
  final int craftProbabilityPerMille;

  /// ISO 4217 currency code of the currency in which value of the gift is represented; may be empty if unavailable
  final String valueCurrency;

  /// Estimated value of the gift; in the smallest units of the currency; 0 if unavailable
  final int valueAmount;

  /// Estimated value of the gift in USD; in USD cents; 0 if unavailable
  final int valueUsdAmount;

  const UpgradedGift({
    required this.id,
    required this.regularGiftId,
    required this.publisherChatId,
    required this.title,
    required this.name,
    required this.number,
    required this.totalUpgradedCount,
    required this.maxUpgradedCount,
    required this.isBurned,
    required this.isCrafted,
    required this.isPremium,
    required this.isThemeAvailable,
    required this.usedThemeChatId,
    this.hostId,
    this.ownerId,
    required this.ownerAddress,
    required this.ownerName,
    required this.giftAddress,
    this.model,
    this.symbol,
    this.backdrop,
    this.originalDetails,
    this.colors,
    this.resaleParameters,
    required this.canSendPurchaseOffer,
    required this.craftProbabilityPerMille,
    required this.valueCurrency,
    required this.valueAmount,
    required this.valueUsdAmount,
  });

  static const String constructorType = 'upgradedGift';
  @override
  String get tdType => constructorType;

  factory UpgradedGift.fromJson(Map<String, Object?> json) => UpgradedGift(
    id: int.parse((json['id'] as String?) ?? '0'),
    regularGiftId: int.parse((json['regular_gift_id'] as String?) ?? '0'),
    publisherChatId: ((json['publisher_chat_id'] as num?) ?? 0).toInt(),
    title: ((json['title'] as String?) ?? ''),
    name: ((json['name'] as String?) ?? ''),
    number: ((json['number'] as num?) ?? 0).toInt(),
    totalUpgradedCount: ((json['total_upgraded_count'] as num?) ?? 0).toInt(),
    maxUpgradedCount: ((json['max_upgraded_count'] as num?) ?? 0).toInt(),
    isBurned: ((json['is_burned'] as bool?) ?? false),
    isCrafted: ((json['is_crafted'] as bool?) ?? false),
    isPremium: ((json['is_premium'] as bool?) ?? false),
    isThemeAvailable: ((json['is_theme_available'] as bool?) ?? false),
    usedThemeChatId: ((json['used_theme_chat_id'] as num?) ?? 0).toInt(),
    hostId: json['host_id'] == null
        ? null
        : MessageSender.fromJson(json['host_id'] as Map<String, Object?>),
    ownerId: json['owner_id'] == null
        ? null
        : MessageSender.fromJson(json['owner_id'] as Map<String, Object?>),
    ownerAddress: ((json['owner_address'] as String?) ?? ''),
    ownerName: ((json['owner_name'] as String?) ?? ''),
    giftAddress: ((json['gift_address'] as String?) ?? ''),
    model: json['model'] == null
        ? null
        : UpgradedGiftModel.fromJson(json['model'] as Map<String, Object?>),
    symbol: json['symbol'] == null
        ? null
        : UpgradedGiftSymbol.fromJson(json['symbol'] as Map<String, Object?>),
    backdrop: json['backdrop'] == null
        ? null
        : UpgradedGiftBackdrop.fromJson(
            json['backdrop'] as Map<String, Object?>,
          ),
    originalDetails: json['original_details'] == null
        ? null
        : UpgradedGiftOriginalDetails.fromJson(
            json['original_details'] as Map<String, Object?>,
          ),
    colors: json['colors'] == null
        ? null
        : UpgradedGiftColors.fromJson(json['colors'] as Map<String, Object?>),
    resaleParameters: json['resale_parameters'] == null
        ? null
        : GiftResaleParameters.fromJson(
            json['resale_parameters'] as Map<String, Object?>,
          ),
    canSendPurchaseOffer: ((json['can_send_purchase_offer'] as bool?) ?? false),
    craftProbabilityPerMille:
        ((json['craft_probability_per_mille'] as num?) ?? 0).toInt(),
    valueCurrency: ((json['value_currency'] as String?) ?? ''),
    valueAmount: ((json['value_amount'] as num?) ?? 0).toInt(),
    valueUsdAmount: ((json['value_usd_amount'] as num?) ?? 0).toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id.toString(),
    'regular_gift_id': regularGiftId.toString(),
    'publisher_chat_id': publisherChatId,
    'title': title,
    'name': name,
    'number': number,
    'total_upgraded_count': totalUpgradedCount,
    'max_upgraded_count': maxUpgradedCount,
    'is_burned': isBurned,
    'is_crafted': isCrafted,
    'is_premium': isPremium,
    'is_theme_available': isThemeAvailable,
    'used_theme_chat_id': usedThemeChatId,
    'host_id': hostId?.toJson(),
    'owner_id': ownerId?.toJson(),
    'owner_address': ownerAddress,
    'owner_name': ownerName,
    'gift_address': giftAddress,
    'model': model?.toJson(),
    'symbol': symbol?.toJson(),
    'backdrop': backdrop?.toJson(),
    'original_details': originalDetails?.toJson(),
    'colors': colors?.toJson(),
    'resale_parameters': resaleParameters?.toJson(),
    'can_send_purchase_offer': canSendPurchaseOffer,
    'craft_probability_per_mille': craftProbabilityPerMille,
    'value_currency': valueCurrency,
    'value_amount': valueAmount,
    'value_usd_amount': valueUsdAmount,
  };
}

/// Contains information about value of an upgraded gift
final class UpgradedGiftValueInfo extends TdObject {
  /// ISO 4217 currency code of the currency in which the prices are represented
  final String currency;

  /// Estimated value of the gift; in the smallest units of the currency
  final int value;

  /// True, if the value is calculated as average value of similar sold gifts. Otherwise, it is based on the sale price of the gift
  final bool isValueAverage;

  /// Point in time (Unix timestamp) when the corresponding regular gift was originally purchased
  final int initialSaleDate;

  /// The Telegram Star amount that was paid for the gift
  final int initialSaleStarCount;

  /// Initial price of the gift; in the smallest units of the currency
  final int initialSalePrice;

  /// Point in time (Unix timestamp) when the upgraded gift was purchased last time; 0 if never
  final int lastSaleDate;

  /// Last purchase price of the gift; in the smallest units of the currency; 0 if the gift has never been resold
  final int lastSalePrice;

  /// True, if the last sale was completed on Fragment
  final bool isLastSaleOnFragment;

  /// The current minimum price of gifts upgraded from the same gift; in the smallest units of the currency; 0 if there are no such gifts
  final int minimumPrice;

  /// The average sale price in the last month of gifts upgraded from the same gift; in the smallest units of the currency; 0 if there were no such sales
  final int averageSalePrice;

  /// Number of gifts upgraded from the same gift being resold on Telegram
  final int telegramListedGiftCount;

