        lastSaleDate: ((json['last_sale_date'] as num?) ?? 0).toInt(),
        lastSalePrice: ((json['last_sale_price'] as num?) ?? 0).toInt(),
        isLastSaleOnFragment:
            ((json['is_last_sale_on_fragment'] as bool?) ?? false),
        minimumPrice: ((json['minimum_price'] as num?) ?? 0).toInt(),
