/// Contains result of gift upgrading
final class UpgradeGiftResult extends TdObject {
  /// The upgraded gift
  final UpgradedGift? gift;

  /// Unique identifier of the received gift for the current user
  final String receivedGiftId;

  /// True, if the gift is displayed on the user's or the channel's profile page
  final bool isSaved;

  /// True, if the gift can be transferred to another owner
  final bool canBeTransferred;

  /// Number of Telegram Stars that must be paid to transfer the upgraded gift
  final int transferStarCount;

  /// Number of Telegram Stars that must be paid to drop original details of the upgraded gift; 0 if not available
  final int dropOriginalDetailsStarCount;

  /// Point in time (Unix timestamp) when the gift can be transferred to another owner; can be in the past; 0 if the gift can be transferred immediately or transfer isn't possible
  final int nextTransferDate;

  /// Point in time (Unix timestamp) when the gift can be resold to another user; can be in the past; 0 if the gift can't be resold; only for the receiver of the gift
  final int nextResaleDate;

  /// Point in time (Unix timestamp) when the gift can be transferred to the TON blockchain as an NFT; can be in the past
  final int exportDate;

  const UpgradeGiftResult({
    this.gift,
    required this.receivedGiftId,
    required this.isSaved,
    required this.canBeTransferred,
    required this.transferStarCount,
    required this.dropOriginalDetailsStarCount,
    required this.nextTransferDate,
    required this.nextResaleDate,
    required this.exportDate,
  });

  static const String constructorType = 'upgradeGiftResult';
  @override
  String get tdType => constructorType;

  factory UpgradeGiftResult.fromJson(Map<String, Object?> json) =>
      UpgradeGiftResult(
        gift: json['gift'] == null
            ? null
            : UpgradedGift.fromJson(json['gift'] as Map<String, Object?>),
        receivedGiftId: ((json['received_gift_id'] as String?) ?? ''),
        isSaved: ((json['is_saved'] as bool?) ?? false),
        canBeTransferred: ((json['can_be_transferred'] as bool?) ?? false),
        transferStarCount: ((json['transfer_star_count'] as num?) ?? 0).toInt(),
        dropOriginalDetailsStarCount:
            ((json['drop_original_details_star_count'] as num?) ?? 0).toInt(),
        nextTransferDate: ((json['next_transfer_date'] as num?) ?? 0).toInt(),
        nextResaleDate: ((json['next_resale_date'] as num?) ?? 0).toInt(),
        exportDate: ((json['export_date'] as num?) ?? 0).toInt(),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'gift': gift?.toJson(),
    'received_gift_id': receivedGiftId,
    'is_saved': isSaved,
    'can_be_transferred': canBeTransferred,
    'transfer_star_count': transferStarCount,
    'drop_original_details_star_count': dropOriginalDetailsStarCount,
    'next_transfer_date': nextTransferDate,
    'next_resale_date': nextResaleDate,
    'export_date': exportDate,
  };
}

/// Contains result of gift crafting
sealed class CraftGiftResult extends TdObject {
  const CraftGiftResult();

  static CraftGiftResult fromJson(
    Map<String, Object?> json,
  ) => switch (json['@type']) {
    'craftGiftResultSuccess' => CraftGiftResultSuccess.fromJson(json),
    'craftGiftResultTooEarly' => CraftGiftResultTooEarly.fromJson(json),
    'craftGiftResultInvalidGift' => CraftGiftResultInvalidGift.fromJson(json),
    'craftGiftResultFail' => CraftGiftResultFail.fromJson(json),
    final t => throw ArgumentError('unknown CraftGiftResult constructor: $t'),
  };
}

/// Crafting was successful
final class CraftGiftResultSuccess extends CraftGiftResult {
  /// The created gift
  final UpgradedGift? gift;

  /// Unique identifier of the received gift for the current user
  final String receivedGiftId;

  const CraftGiftResultSuccess({this.gift, required this.receivedGiftId});

  static const String constructorType = 'craftGiftResultSuccess';
  @override
  String get tdType => constructorType;

  factory CraftGiftResultSuccess.fromJson(Map<String, Object?> json) =>
      CraftGiftResultSuccess(
        gift: json['gift'] == null
            ? null
            : UpgradedGift.fromJson(json['gift'] as Map<String, Object?>),
        receivedGiftId: ((json['received_gift_id'] as String?) ?? ''),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'gift': gift?.toJson(),
    'received_gift_id': receivedGiftId,
  };
}

/// Crafting isn't possible because one of the gifts can't be used for crafting yet
final class CraftGiftResultTooEarly extends CraftGiftResult {
  /// Time left before the gift can be used for crafting
  final int retryAfter;

  const CraftGiftResultTooEarly({required this.retryAfter});

  static const String constructorType = 'craftGiftResultTooEarly';
  @override
  String get tdType => constructorType;

  factory CraftGiftResultTooEarly.fromJson(Map<String, Object?> json) =>
      CraftGiftResultTooEarly(
        retryAfter: ((json['retry_after'] as num?) ?? 0).toInt(),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'retry_after': retryAfter,
  };
}

/// Crafting isn't possible because one of the gifts isn't suitable for crafting
final class CraftGiftResultInvalidGift extends CraftGiftResult {
  const CraftGiftResultInvalidGift();

  static const String constructorType = 'craftGiftResultInvalidGift';
  @override
  String get tdType => constructorType;

  factory CraftGiftResultInvalidGift.fromJson(Map<String, Object?> json) =>
      CraftGiftResultInvalidGift();

  @override
  Map<String, Object?> toJson() => {'@type': constructorType};
}

/// Crafting has failed
final class CraftGiftResultFail extends CraftGiftResult {
  const CraftGiftResultFail();

  static const String constructorType = 'craftGiftResultFail';
  @override
  String get tdType => constructorType;

  factory CraftGiftResultFail.fromJson(Map<String, Object?> json) =>
      CraftGiftResultFail();

  @override
  Map<String, Object?> toJson() => {'@type': constructorType};
}

