      GiftsForCrafting(
        totalCount: ((json['total_count'] as num?) ?? 0).toInt(),
        gifts: ((json['gifts'] as List?) ?? const [])
            .map((e) => ReceivedGift.fromJson(e as Map<String, Object?>))
            .toList(),
        attributePersistenceProbabilities:
            ((json['attribute_persistence_probabilities'] as List?) ?? const [])
                .map(
