          StarTransactionTypePremiumPurchase.fromJson(json),
        'starTransactionTypeBusinessBotTransferSend' =>
          StarTransactionTypeBusinessBotTransferSend.fromJson(json),
        'starTransactionTypeBusinessBotTransferReceive' =>
          StarTransactionTypeBusinessBotTransferReceive.fromJson(json),
        'starTransactionTypePublicPostSearch' =>
          StarTransactionTypePublicPostSearch.fromJson(json),
        'starTransactionTypeUnsupported' =>
          StarTransactionTypeUnsupported.fromJson(json),
        final t => throw ArgumentError(
          'unknown StarTransactionType constructor: $t',
        ),
      };
}

