/// Represents a transaction changing the amount of owned Telegram Stars
final class StarTransaction extends TdObject {
  /// Unique identifier of the transaction
  final String id;

  /// The amount of added owned Telegram Stars; negative for outgoing transactions
  final StarAmount? starAmount;

  /// True, if the transaction is a refund of a previous transaction
  final bool isRefund;

  /// Point in time (Unix timestamp) when the transaction was completed
  final int date;

  /// Type of the transaction
  final StarTransactionType? type;

  const StarTransaction({
    required this.id,
    this.starAmount,
    required this.isRefund,
    required this.date,
    this.type,
  });

  static const String constructorType = 'starTransaction';
  @override
  String get tdType => constructorType;

  factory StarTransaction.fromJson(Map<String, Object?> json) =>
      StarTransaction(
        id: ((json['id'] as String?) ?? ''),
        starAmount: json['star_amount'] == null
            ? null
            : StarAmount.fromJson(json['star_amount'] as Map<String, Object?>),
        isRefund: ((json['is_refund'] as bool?) ?? false),
        date: ((json['date'] as num?) ?? 0).toInt(),
        type: json['type'] == null
            ? null
            : StarTransactionType.fromJson(
                json['type'] as Map<String, Object?>,
              ),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id,
    'star_amount': starAmount?.toJson(),
    'is_refund': isRefund,
    'date': date,
    'type': type?.toJson(),
  };
}

/// Represents a list of Telegram Star transactions
final class StarTransactions extends TdObject {
  /// The amount of owned Telegram Stars
  final StarAmount? starAmount;

  /// List of transactions with Telegram Stars
  final List<StarTransaction> transactions;

  /// The offset for the next request. If empty, then there are no more results
  final String nextOffset;

  const StarTransactions({
    this.starAmount,
    required this.transactions,
    required this.nextOffset,
  });

  static const String constructorType = 'starTransactions';
  @override
  String get tdType => constructorType;

  factory StarTransactions.fromJson(Map<String, Object?> json) =>
      StarTransactions(
        starAmount: json['star_amount'] == null
            ? null
            : StarAmount.fromJson(json['star_amount'] as Map<String, Object?>),
        transactions: ((json['transactions'] as List?) ?? const [])
            .map((e) => StarTransaction.fromJson(e as Map<String, Object?>))
            .toList(),
        nextOffset: ((json['next_offset'] as String?) ?? ''),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'star_amount': starAmount?.toJson(),
    'transactions': transactions.map((e) => e.toJson()).toList(),
    'next_offset': nextOffset,
  };
}

/// Describes type of transaction with TON Grams
sealed class TonTransactionType extends TdObject {
  const TonTransactionType();

  static TonTransactionType fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'tonTransactionTypeFragmentDeposit' =>
          TonTransactionTypeFragmentDeposit.fromJson(json),
        'tonTransactionTypeFragmentWithdrawal' =>
          TonTransactionTypeFragmentWithdrawal.fromJson(json),
        'tonTransactionTypeSuggestedPostPayment' =>
          TonTransactionTypeSuggestedPostPayment.fromJson(json),
        'tonTransactionTypeGiftPurchaseOffer' =>
          TonTransactionTypeGiftPurchaseOffer.fromJson(json),
        'tonTransactionTypeUpgradedGiftPurchase' =>
          TonTransactionTypeUpgradedGiftPurchase.fromJson(json),
        'tonTransactionTypeUpgradedGiftSale' =>
          TonTransactionTypeUpgradedGiftSale.fromJson(json),
        'tonTransactionTypeStakeDiceStake' =>
          TonTransactionTypeStakeDiceStake.fromJson(json),
        'tonTransactionTypeStakeDicePayout' =>
          TonTransactionTypeStakeDicePayout.fromJson(json),
        'tonTransactionTypeUnsupported' =>
          TonTransactionTypeUnsupported.fromJson(json),
        final t => throw ArgumentError(
          'unknown TonTransactionType constructor: $t',
        ),
      };
}

