    isContact: ((json['is_contact'] as bool?) ?? false),
    isMutualContact: ((json['is_mutual_contact'] as bool?) ?? false),
    isCloseFriend: ((json['is_close_friend'] as bool?) ?? false),
    verificationStatus: json['verification_status'] == null
        ? null
