/// Contains information about a bot
final class BotInfo extends TdObject {
  /// The text that is shown on the bot's profile page and is sent together with the link when users share the bot
  final String shortDescription;

  /// The text shown in the chat with the bot if the chat is empty
  final String description;

  /// Photo shown in the chat with the bot if the chat is empty; may be null
  final Photo? photo;

  /// Animation shown in the chat with the bot if the chat is empty; may be null
  final Animation? animation;

  /// Identifier of the bot, which manages the bot; 0 if none or unknown; for owner of the bot only
  final int managerBotUserId;

  /// Information about a button to show instead of the bot commands menu button; may be null if ordinary bot commands menu must be shown
  final BotMenuButton? menuButton;

  /// List of the bot commands
  final List<BotCommand> commands;

  /// The HTTP link to the privacy policy of the bot. If empty, then /privacy command must be used if supported by the bot. If the command isn't supported, then https://telegram.org/privacy-tpa must be opened
  final String privacyPolicyUrl;

  /// Default administrator rights for adding the bot to basic group and supergroup chats; may be null
  final ChatAdministratorRights? defaultGroupAdministratorRights;

  /// Default administrator rights for adding the bot to channels; may be null
  final ChatAdministratorRights? defaultChannelAdministratorRights;

  /// Information about the affiliate program of the bot; may be null if none
  final AffiliateProgramInfo? affiliateProgram;

  /// Default light background color for bot Web Apps; -1 if not specified
  final int webAppBackgroundLightColor;

  /// Default dark background color for bot Web Apps; -1 if not specified
  final int webAppBackgroundDarkColor;

  /// Default light header color for bot Web Apps; -1 if not specified
  final int webAppHeaderLightColor;

  /// Default dark header color for bot Web Apps; -1 if not specified
  final int webAppHeaderDarkColor;

  /// Parameters of the verification that can be provided by the bot; may be null if none or the current user isn't the owner of the bot
  final BotVerificationParameters? verificationParameters;

  /// True, if the bot's revenue statistics are available to the current user
  final bool canGetRevenueStatistics;

  /// True, if the bot can manage emoji status of the current user
  final bool canManageEmojiStatus;

  /// True, if the bot has media previews
  final bool hasMediaPreviews;

  /// The internal link, which can be used to edit bot commands; may be null
  final InternalLinkType? editCommandsLink;

  /// The internal link, which can be used to edit bot description; may be null
  final InternalLinkType? editDescriptionLink;

  /// The internal link, which can be used to edit the photo or animation shown in the chat with the bot if the chat is empty; may be null
  final InternalLinkType? editDescriptionMediaLink;

  /// The internal link, which can be used to edit bot settings; may be null
  final InternalLinkType? editSettingsLink;

  const BotInfo({
    required this.shortDescription,
    required this.description,
    this.photo,
    this.animation,
    required this.managerBotUserId,
    this.menuButton,
    required this.commands,
    required this.privacyPolicyUrl,
    this.defaultGroupAdministratorRights,
    this.defaultChannelAdministratorRights,
    this.affiliateProgram,
    required this.webAppBackgroundLightColor,
    required this.webAppBackgroundDarkColor,
    required this.webAppHeaderLightColor,
    required this.webAppHeaderDarkColor,
    this.verificationParameters,
    required this.canGetRevenueStatistics,
    required this.canManageEmojiStatus,
    required this.hasMediaPreviews,
    this.editCommandsLink,
    this.editDescriptionLink,
    this.editDescriptionMediaLink,
    this.editSettingsLink,
  });

  static const String constructorType = 'botInfo';
  @override
  String get tdType => constructorType;

  factory BotInfo.fromJson(Map<String, Object?> json) => BotInfo(
    shortDescription: ((json['short_description'] as String?) ?? ''),
    description: ((json['description'] as String?) ?? ''),
    photo: json['photo'] == null
        ? null
        : Photo.fromJson(json['photo'] as Map<String, Object?>),
    animation: json['animation'] == null
        ? null
        : Animation.fromJson(json['animation'] as Map<String, Object?>),
    managerBotUserId: ((json['manager_bot_user_id'] as num?) ?? 0).toInt(),
    menuButton: json['menu_button'] == null
        ? null
        : BotMenuButton.fromJson(json['menu_button'] as Map<String, Object?>),
    commands: ((json['commands'] as List?) ?? const [])
        .map((e) => BotCommand.fromJson(e as Map<String, Object?>))
        .toList(),
    privacyPolicyUrl: ((json['privacy_policy_url'] as String?) ?? ''),
    defaultGroupAdministratorRights:
        json['default_group_administrator_rights'] == null
        ? null
        : ChatAdministratorRights.fromJson(
            json['default_group_administrator_rights'] as Map<String, Object?>,
          ),
    defaultChannelAdministratorRights:
        json['default_channel_administrator_rights'] == null
        ? null
        : ChatAdministratorRights.fromJson(
            json['default_channel_administrator_rights']
                as Map<String, Object?>,
          ),
    affiliateProgram: json['affiliate_program'] == null
        ? null
        : AffiliateProgramInfo.fromJson(
            json['affiliate_program'] as Map<String, Object?>,
          ),
    webAppBackgroundLightColor:
        ((json['web_app_background_light_color'] as num?) ?? 0).toInt(),
    webAppBackgroundDarkColor:
        ((json['web_app_background_dark_color'] as num?) ?? 0).toInt(),
    webAppHeaderLightColor: ((json['web_app_header_light_color'] as num?) ?? 0)
        .toInt(),
    webAppHeaderDarkColor: ((json['web_app_header_dark_color'] as num?) ?? 0)
        .toInt(),
    verificationParameters: json['verification_parameters'] == null
        ? null
        : BotVerificationParameters.fromJson(
            json['verification_parameters'] as Map<String, Object?>,
          ),
    canGetRevenueStatistics:
        ((json['can_get_revenue_statistics'] as bool?) ?? false),
    canManageEmojiStatus: ((json['can_manage_emoji_status'] as bool?) ?? false),
    hasMediaPreviews: ((json['has_media_previews'] as bool?) ?? false),
    editCommandsLink: json['edit_commands_link'] == null
        ? null
        : InternalLinkType.fromJson(
            json['edit_commands_link'] as Map<String, Object?>,
          ),
    editDescriptionLink: json['edit_description_link'] == null
        ? null
        : InternalLinkType.fromJson(
            json['edit_description_link'] as Map<String, Object?>,
          ),
    editDescriptionMediaLink: json['edit_description_media_link'] == null
        ? null
        : InternalLinkType.fromJson(
            json['edit_description_media_link'] as Map<String, Object?>,
          ),
    editSettingsLink: json['edit_settings_link'] == null
        ? null
        : InternalLinkType.fromJson(
            json['edit_settings_link'] as Map<String, Object?>,
          ),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'short_description': shortDescription,
    'description': description,
    'photo': photo?.toJson(),
    'animation': animation?.toJson(),
    'manager_bot_user_id': managerBotUserId,
    'menu_button': menuButton?.toJson(),
    'commands': commands.map((e) => e.toJson()).toList(),
    'privacy_policy_url': privacyPolicyUrl,
    'default_group_administrator_rights': defaultGroupAdministratorRights
        ?.toJson(),
    'default_channel_administrator_rights': defaultChannelAdministratorRights
        ?.toJson(),
    'affiliate_program': affiliateProgram?.toJson(),
    'web_app_background_light_color': webAppBackgroundLightColor,
    'web_app_background_dark_color': webAppBackgroundDarkColor,
    'web_app_header_light_color': webAppHeaderLightColor,
    'web_app_header_dark_color': webAppHeaderDarkColor,
    'verification_parameters': verificationParameters?.toJson(),
    'can_get_revenue_statistics': canGetRevenueStatistics,
    'can_manage_emoji_status': canManageEmojiStatus,
    'has_media_previews': hasMediaPreviews,
    'edit_commands_link': editCommandsLink?.toJson(),
    'edit_description_link': editDescriptionLink?.toJson(),
    'edit_description_media_link': editDescriptionMediaLink?.toJson(),
    'edit_settings_link': editSettingsLink?.toJson(),
  };
}

/// Contains full information about a user
final class UserFullInfo extends TdObject {
  /// User profile photo set by the current user for the contact; may be null. If null and user.profile_photo is null, then the photo is empty; otherwise, it is unknown. If non-null, then it is the same photo as in user.profile_photo and chat.photo. This photo isn't returned in the list of user photos
  final ChatPhoto? personalPhoto;

  /// User profile photo; may be null. If null and user.profile_photo is null, then the photo is empty; otherwise, it is unknown. If non-null and personal_photo is null, then it is the same photo as in user.profile_photo and chat.photo
  final ChatPhoto? photo;

  /// User profile photo visible if the main photo is hidden by privacy settings; may be null. If null and user.profile_photo is null, then the photo is empty; otherwise, it is unknown. If non-null and both photo and personal_photo are null, then it is the same photo as in user.profile_photo and chat.photo. This photo isn't returned in the list of user photos
  final ChatPhoto? publicPhoto;

  /// Identifier of the community to which chat with the bot was added; for bots only
  final int communityId;

  /// Block list to which the user is added; may be null if none
  final BlockList? blockList;

  /// True, if the user can be called
  final bool canBeCalled;

  /// True, if a video call can be created with the user
  final bool supportsVideoCalls;

  /// True, if the user can't be called due to their privacy settings
  final bool hasPrivateCalls;

  /// True, if the user can't be linked in forwarded messages due to their privacy settings
  final bool hasPrivateForwards;

  /// True, if voice and video notes can't be sent or forwarded to the user
  final bool hasRestrictedVoiceAndVideoNoteMessages;

  /// True, if the user has posted to profile stories
  final bool hasPostedToProfileStories;

  /// True, if the user always enabled sponsored messages; known only for the current user
  final bool hasSponsoredMessagesEnabled;

  /// True, if the current user needs to explicitly allow to share their phone number with the user when the method addContact is used
  final bool needPhoneNumberPrivacyException;

  /// True, if the user set chat background for both chat users and it wasn't reverted yet
  final bool setChatBackground;

  /// True, if the user uses an unofficial application that poses a security risk
  final bool usesUnofficialApp;

  /// A short user bio; may be null for bots
  final FormattedText? bio;

  /// Birthdate of the user; may be null if unknown
  final Birthdate? birthdate;

  /// Identifier of the personal chat of the user; 0 if none
  final int personalChatId;

  /// Number of saved to profile gifts for other users or the total number of received gifts for the current user
  final int giftCount;

  /// Number of group chats where both the other user and the current user are a member; 0 for the current user
  final int groupInCommonCount;

  /// Number of Telegram Stars that must be paid by the user for each sent message to the current user
  final int incomingPaidMessageStarCount;

  /// Number of Telegram Stars that must be paid by the current user for each sent message to the user
  final int outgoingPaidMessageStarCount;

  /// Settings for gift receiving for the user
  final GiftSettings? giftSettings;

  /// Information about verification status of the user provided by a bot; may be null if none or unknown
  final BotVerification? botVerification;

  /// The main tab chosen by the user; may be null if not chosen manually
  final ProfileTab? mainProfileTab;

  /// The first audio file added to the user's profile; may be null if none
  final Audio? firstProfileAudio;

  /// The current rating of the user; may be null if none
  final UserRating? rating;

  /// The rating of the user after the next change; may be null if the user isn't the current user or there are no pending rating changes
  final UserRating? pendingRating;

  /// Unix timestamp when rating of the user will change to pending_rating; 0 if the user isn't the current user or there are no pending rating changes
  final int pendingRatingDate;

  /// Note added to the user's contact; may be null if none
  final FormattedText? note;

  /// Information about business settings for Telegram Business accounts; may be null if none
  final BusinessInfo? businessInfo;

  /// For bots, information about the bot; may be null if the user isn't a bot
  final BotInfo? botInfo;

  const UserFullInfo({
    this.personalPhoto,
    this.photo,
    this.publicPhoto,
    required this.communityId,
    this.blockList,
    required this.canBeCalled,
    required this.supportsVideoCalls,
    required this.hasPrivateCalls,
    required this.hasPrivateForwards,
    required this.hasRestrictedVoiceAndVideoNoteMessages,
    required this.hasPostedToProfileStories,
    required this.hasSponsoredMessagesEnabled,
    required this.needPhoneNumberPrivacyException,
    required this.setChatBackground,
    required this.usesUnofficialApp,
    this.bio,
    this.birthdate,
    required this.personalChatId,
    required this.giftCount,
    required this.groupInCommonCount,
    required this.incomingPaidMessageStarCount,
    required this.outgoingPaidMessageStarCount,
    this.giftSettings,
    this.botVerification,
    this.mainProfileTab,
    this.firstProfileAudio,
    this.rating,
    this.pendingRating,
    required this.pendingRatingDate,
    this.note,
    this.businessInfo,
    this.botInfo,
  });

  static const String constructorType = 'userFullInfo';
  @override
  String get tdType => constructorType;

  factory UserFullInfo.fromJson(Map<String, Object?> json) => UserFullInfo(
    personalPhoto: json['personal_photo'] == null
        ? null
        : ChatPhoto.fromJson(json['personal_photo'] as Map<String, Object?>),
    photo: json['photo'] == null
        ? null
        : ChatPhoto.fromJson(json['photo'] as Map<String, Object?>),
    publicPhoto: json['public_photo'] == null
        ? null
        : ChatPhoto.fromJson(json['public_photo'] as Map<String, Object?>),
    communityId: ((json['community_id'] as num?) ?? 0).toInt(),
    blockList: json['block_list'] == null
        ? null
        : BlockList.fromJson(json['block_list'] as Map<String, Object?>),
    canBeCalled: ((json['can_be_called'] as bool?) ?? false),
    supportsVideoCalls: ((json['supports_video_calls'] as bool?) ?? false),
    hasPrivateCalls: ((json['has_private_calls'] as bool?) ?? false),
    hasPrivateForwards: ((json['has_private_forwards'] as bool?) ?? false),
    hasRestrictedVoiceAndVideoNoteMessages:
        ((json['has_restricted_voice_and_video_note_messages'] as bool?) ??
        false),
    hasPostedToProfileStories:
        ((json['has_posted_to_profile_stories'] as bool?) ?? false),
    hasSponsoredMessagesEnabled:
        ((json['has_sponsored_messages_enabled'] as bool?) ?? false),
    needPhoneNumberPrivacyException:
        ((json['need_phone_number_privacy_exception'] as bool?) ?? false),
    setChatBackground: ((json['set_chat_background'] as bool?) ?? false),
    usesUnofficialApp: ((json['uses_unofficial_app'] as bool?) ?? false),
    bio: json['bio'] == null
        ? null
        : FormattedText.fromJson(json['bio'] as Map<String, Object?>),
    birthdate: json['birthdate'] == null
        ? null
        : Birthdate.fromJson(json['birthdate'] as Map<String, Object?>),
    personalChatId: ((json['personal_chat_id'] as num?) ?? 0).toInt(),
    giftCount: ((json['gift_count'] as num?) ?? 0).toInt(),
    groupInCommonCount: ((json['group_in_common_count'] as num?) ?? 0).toInt(),
    incomingPaidMessageStarCount:
        ((json['incoming_paid_message_star_count'] as num?) ?? 0).toInt(),
    outgoingPaidMessageStarCount:
        ((json['outgoing_paid_message_star_count'] as num?) ?? 0).toInt(),
    giftSettings: json['gift_settings'] == null
        ? null
        : GiftSettings.fromJson(json['gift_settings'] as Map<String, Object?>),
    botVerification: json['bot_verification'] == null
        ? null
        : BotVerification.fromJson(
            json['bot_verification'] as Map<String, Object?>,
          ),
    mainProfileTab: json['main_profile_tab'] == null
        ? null
        : ProfileTab.fromJson(json['main_profile_tab'] as Map<String, Object?>),
    firstProfileAudio: json['first_profile_audio'] == null
        ? null
        : Audio.fromJson(json['first_profile_audio'] as Map<String, Object?>),
    rating: json['rating'] == null
        ? null
        : UserRating.fromJson(json['rating'] as Map<String, Object?>),
    pendingRating: json['pending_rating'] == null
        ? null
        : UserRating.fromJson(json['pending_rating'] as Map<String, Object?>),
    pendingRatingDate: ((json['pending_rating_date'] as num?) ?? 0).toInt(),
    note: json['note'] == null
        ? null
        : FormattedText.fromJson(json['note'] as Map<String, Object?>),
    businessInfo: json['business_info'] == null
        ? null
        : BusinessInfo.fromJson(json['business_info'] as Map<String, Object?>),
    botInfo: json['bot_info'] == null
        ? null
