  factory Users.fromJson(Map<String, Object?> json) => Users(
    totalCount: ((json['total_count'] as num?) ?? 0).toInt(),
    userIds: ((json['user_ids'] as List?) ?? const [])
        .map((e) => ((e as num?) ?? 0).toInt())
        .toList(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'total_count': totalCount,
    'user_ids': userIds.map((e) => e).toList(),
  };
}

