/// Describes the current secret chat state
sealed class SecretChatState extends TdObject {
  const SecretChatState();

  static SecretChatState fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'secretChatStatePending' => SecretChatStatePending.fromJson(json),
        'secretChatStateReady' => SecretChatStateReady.fromJson(json),
        'secretChatStateClosed' => SecretChatStateClosed.fromJson(json),
        final t => throw ArgumentError(
          'unknown SecretChatState constructor: $t',
        ),
      };
}

/// The secret chat is not yet created; waiting for the other user to get online
final class SecretChatStatePending extends SecretChatState {
  const SecretChatStatePending();

  static const String constructorType = 'secretChatStatePending';
  @override
  String get tdType => constructorType;

  factory SecretChatStatePending.fromJson(Map<String, Object?> json) =>
      SecretChatStatePending();

  @override
  Map<String, Object?> toJson() => {'@type': constructorType};
}

/// The secret chat is ready to use
final class SecretChatStateReady extends SecretChatState {
  const SecretChatStateReady();

  static const String constructorType = 'secretChatStateReady';
  @override
  String get tdType => constructorType;

  factory SecretChatStateReady.fromJson(Map<String, Object?> json) =>
      SecretChatStateReady();

  @override
  Map<String, Object?> toJson() => {'@type': constructorType};
}

/// The secret chat is closed
final class SecretChatStateClosed extends SecretChatState {
  const SecretChatStateClosed();

  static const String constructorType = 'secretChatStateClosed';
  @override
  String get tdType => constructorType;

  factory SecretChatStateClosed.fromJson(Map<String, Object?> json) =>
      SecretChatStateClosed();

  @override
  Map<String, Object?> toJson() => {'@type': constructorType};
}

/// Represents a secret chat
final class SecretChat extends TdObject {
  /// Secret chat identifier
  final int id;

  /// Identifier of the chat partner
  final int userId;

  /// State of the secret chat
  final SecretChatState? state;

  /// True, if the chat was created by the current user; false otherwise
  final bool isOutbound;

  /// Hash of the currently used key for comparison with the hash of the chat partner's key. This is a string of 36 little-endian bytes, which must be split into groups of 2 bits, each denoting a pixel of one of 4 colors FFFFFF, D5E6F3, 2D5775, and 2F99C9. The pixels must be used to make a 12x12 square image filled from left to right, top to bottom. Alternatively, the first 32 bytes of the hash can be converted to the hexadecimal format and printed as 32 2-digit hex numbers
  final String keyHash;

  /// Secret chat layer; determines features supported by the chat partner's application. Nested text entities and underline and strikethrough entities are supported if the layer >= 101, files bigger than 2000MB are supported if the layer >= 143, spoiler and custom emoji text entities are supported if the layer >= 144
  final int layer;

  const SecretChat({
    required this.id,
    required this.userId,
    this.state,
    required this.isOutbound,
    required this.keyHash,
    required this.layer,
  });

  static const String constructorType = 'secretChat';
  @override
  String get tdType => constructorType;

  factory SecretChat.fromJson(Map<String, Object?> json) => SecretChat(
    id: ((json['id'] as num?) ?? 0).toInt(),
    userId: ((json['user_id'] as num?) ?? 0).toInt(),
    state: json['state'] == null
        ? null
        : SecretChatState.fromJson(json['state'] as Map<String, Object?>),
    isOutbound: ((json['is_outbound'] as bool?) ?? false),
    keyHash: ((json['key_hash'] as String?) ?? ''),
    layer: ((json['layer'] as num?) ?? 0).toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id,
    'user_id': userId,
    'state': state?.toJson(),
    'is_outbound': isOutbound,
    'key_hash': keyHash,
    'layer': layer,
  };
}

