          MessageSourceMessageThreadHistory.fromJson(json),
        'messageSourceForumTopicHistory' =>
          MessageSourceForumTopicHistory.fromJson(json),
        'messageSourceDirectMessagesChatTopicHistory' =>
          MessageSourceDirectMessagesChatTopicHistory.fromJson(json),
        'messageSourceHistoryPreview' => MessageSourceHistoryPreview.fromJson(
          json,
        ),
        'messageSourceChatList' => MessageSourceChatList.fromJson(json),
        'messageSourceSearch' => MessageSourceSearch.fromJson(json),
        'messageSourceChatEventLog' => MessageSourceChatEventLog.fromJson(json),
        'messageSourceNotification' => MessageSourceNotification.fromJson(json),
        'messageSourceScreenshot' => MessageSourceScreenshot.fromJson(json),
        'messageSourceOther' => MessageSourceOther.fromJson(json),
        final t => throw ArgumentError('unknown MessageSource constructor: $t'),
      };
}

