/// Describes a sponsored message
final class SponsoredMessage extends TdObject {
  /// Message identifier; unique for the chat to which the sponsored message belongs among both ordinary and sponsored messages
  final int messageId;

  /// True, if the message needs to be labeled as "recommended" instead of "sponsored"
  final bool isRecommended;

  /// True, if the message can be reported to Telegram moderators through reportChatSponsoredMessage
  final bool canBeReported;

  /// Content of the message. Currently, can be only of the types messageText, messageAnimation, messagePhoto, or messageVideo. Video messages can be viewed fullscreen. The content must be fully downloaded before the message is shown
  final MessageContent? content;

  /// Information about the sponsor of the message
  final AdvertisementSponsor? sponsor;

  /// Title of the sponsored message
  final String title;

  /// Text for the message action button
  final String buttonText;

  /// Identifier of the accent color for title, button text and message background
  final int accentColorId;

  /// Identifier of a custom emoji to be shown on the message background; 0 if none
  final int backgroundCustomEmojiId;

  /// If non-empty, additional information about the sponsored message to be shown along with the message
  final String additionalInfo;

  const SponsoredMessage({
    required this.messageId,
    required this.isRecommended,
    required this.canBeReported,
    this.content,
    this.sponsor,
    required this.title,
    required this.buttonText,
    required this.accentColorId,
    required this.backgroundCustomEmojiId,
    required this.additionalInfo,
  });

  static const String constructorType = 'sponsoredMessage';
  @override
  String get tdType => constructorType;

  factory SponsoredMessage.fromJson(Map<String, Object?> json) =>
      SponsoredMessage(
        messageId: ((json['message_id'] as num?) ?? 0).toInt(),
        isRecommended: ((json['is_recommended'] as bool?) ?? false),
        canBeReported: ((json['can_be_reported'] as bool?) ?? false),
        content: json['content'] == null
            ? null
            : MessageContent.fromJson(json['content'] as Map<String, Object?>),
        sponsor: json['sponsor'] == null
            ? null
            : AdvertisementSponsor.fromJson(
                json['sponsor'] as Map<String, Object?>,
              ),
        title: ((json['title'] as String?) ?? ''),
        buttonText: ((json['button_text'] as String?) ?? ''),
        accentColorId: ((json['accent_color_id'] as num?) ?? 0).toInt(),
        backgroundCustomEmojiId: int.parse(
          (json['background_custom_emoji_id'] as String?) ?? '0',
        ),
        additionalInfo: ((json['additional_info'] as String?) ?? ''),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'message_id': messageId,
    'is_recommended': isRecommended,
    'can_be_reported': canBeReported,
    'content': content?.toJson(),
    'sponsor': sponsor?.toJson(),
    'title': title,
    'button_text': buttonText,
    'accent_color_id': accentColorId,
    'background_custom_emoji_id': backgroundCustomEmojiId.toString(),
    'additional_info': additionalInfo,
  };
}

