  final ChatPhotoInfo? photo;

  /// Identifier of the accent color for message sender name, and backgrounds of chat photo, reply header, and link preview
  final int accentColorId;

  /// Identifier of a custom emoji to be shown on the reply header and link preview background for messages sent by the chat; 0 if none
  final int backgroundCustomEmojiId;

  /// Color scheme based on an upgraded gift to be used for the chat instead of accent_color_id and background_custom_emoji_id; may be null if none
  final UpgradedGiftColors? upgradedGiftColors;

  /// Identifier of the profile accent color for the chat's profile; -1 if none
  final int profileAccentColorId;

  /// Identifier of a custom emoji to be shown on the background of the chat's profile; 0 if none
  final int profileBackgroundCustomEmojiId;

  /// Actions that non-administrator chat members are allowed to take in the chat
  final ChatPermissions? permissions;

  /// Last message in the chat; may be null if none or unknown
  final Message? lastMessage;

  /// Positions of the chat in chat lists
  final List<ChatPosition> positions;

  /// Chat lists to which the chat belongs. A chat can have a non-zero position in a chat list even if it doesn't belong to the chat list and have no position in a chat list even if it belongs to the chat list
  final List<ChatList> chatLists;

  /// Identifier of a user or chat that is selected to send messages in the chat; may be null if the user can't change message sender
  final MessageSender? messageSenderId;

  /// Block list to which the chat is added; may be null if none
  final BlockList? blockList;

  /// True, if chat content can't be saved locally, forwarded, or copied
  final bool hasProtectedContent;

  /// True, if translation of all messages in the chat must be suggested to the user
  final bool isTranslatable;

  /// True, if the chat is marked as unread
  final bool isMarkedAsUnread;

  /// True, if the chat is a forum supergroup that must be shown in the "View as topics" mode, or Saved Messages chat that must be shown in the "View as chats"
  final bool viewAsTopics;

  /// True, if the chat has scheduled messages
  final bool hasScheduledMessages;

  /// True, if the chat has welcome messages; for chat administrators with can_change_info administrator right only
  final bool hasWelcomeMessages;

  /// True, if the chat messages can be deleted only for the current user while other users will continue to see the messages
  final bool canBeDeletedOnlyForSelf;

  /// True, if the chat messages can be deleted for all users
  final bool canBeDeletedForAllUsers;

  /// True, if the chat can be reported to Telegram moderators through reportChat or reportChatPhoto
  final bool canBeReported;

  /// Default value of the disable_notification parameter, used when a message is sent to the chat
  final bool defaultDisableNotification;

  /// Number of unread messages in the chat
  final int unreadCount;

  /// Identifier of the last read incoming message
  final int lastReadInboxMessageId;

  /// Identifier of the last read outgoing message
  final int lastReadOutboxMessageId;

  /// Number of unread messages with a mention/reply in the chat
  final int unreadMentionCount;

  /// Number of messages with unread reactions in the chat
  final int unreadReactionCount;

  /// Number of messages with unread poll votes in the chat
  final int unreadPollVoteCount;

  /// Notification settings for the chat
  final ChatNotificationSettings? notificationSettings;

  /// Types of reaction, available in the chat
  final ChatAvailableReactions? availableReactions;

  /// Current message auto-delete or self-destruct timer setting for the chat, in seconds; 0 if disabled. Self-destruct timer in secret chats starts after the message or its content is viewed. Auto-delete timer in other chats starts from the send date
  final int messageAutoDeleteTime;

  /// Emoji status to be shown along with chat title; may be null
  final EmojiStatus? emojiStatus;

  /// Background set for the chat; may be null if none
  final ChatBackground? background;

  /// Theme set for the chat; may be null if none
  final ChatTheme? theme;

  /// Information about actions which must be possible to do through the chat action bar; may be null if none
  final ChatActionBar? actionBar;

  /// Information about bar for managing a business bot in the chat; may be null if none
  final BusinessBotManageBar? businessBotManageBar;

  /// Information about video chat of the chat
  final VideoChat? videoChat;

  /// Information about pending join requests; may be null if none
  final ChatJoinRequestsInfo? pendingJoinRequests;

  /// Identifier of the message from which reply markup needs to be used; 0 if there is no reply markup in the chat
  final int replyMarkupMessageId;

  /// A draft of a message in the chat; may be null if none
  final DraftMessage? draftMessage;

  /// Application-specific data associated with the chat. (For example, the chat scroll position or local chat notification settings can be stored here.) Persistent if the message database is used
  final String clientData;

  const Chat({
    required this.id,
    this.type,
    required this.title,
    this.photo,
    required this.accentColorId,
    required this.backgroundCustomEmojiId,
    this.upgradedGiftColors,
    required this.profileAccentColorId,
    required this.profileBackgroundCustomEmojiId,
    this.permissions,
    this.lastMessage,
    required this.positions,
    required this.chatLists,
    this.messageSenderId,
    this.blockList,
    required this.hasProtectedContent,
    required this.isTranslatable,
    required this.isMarkedAsUnread,
    required this.viewAsTopics,
    required this.hasScheduledMessages,
    required this.hasWelcomeMessages,
    required this.canBeDeletedOnlyForSelf,
    required this.canBeDeletedForAllUsers,
    required this.canBeReported,
    required this.defaultDisableNotification,
    required this.unreadCount,
    required this.lastReadInboxMessageId,
    required this.lastReadOutboxMessageId,
    required this.unreadMentionCount,
    required this.unreadReactionCount,
    required this.unreadPollVoteCount,
    this.notificationSettings,
    this.availableReactions,
    required this.messageAutoDeleteTime,
    this.emojiStatus,
    this.background,
    this.theme,
    this.actionBar,
    this.businessBotManageBar,
    this.videoChat,
    this.pendingJoinRequests,
    required this.replyMarkupMessageId,
    this.draftMessage,
    required this.clientData,
  });

  static const String constructorType = 'chat';
  @override
  String get tdType => constructorType;

  factory Chat.fromJson(Map<String, Object?> json) => Chat(
    id: ((json['id'] as num?) ?? 0).toInt(),
    type: json['type'] == null
        ? null
        : ChatType.fromJson(json['type'] as Map<String, Object?>),
    title: ((json['title'] as String?) ?? ''),
    photo: json['photo'] == null
        ? null
        : ChatPhotoInfo.fromJson(json['photo'] as Map<String, Object?>),
    accentColorId: ((json['accent_color_id'] as num?) ?? 0).toInt(),
    backgroundCustomEmojiId: int.parse(
      (json['background_custom_emoji_id'] as String?) ?? '0',
    ),
    upgradedGiftColors: json['upgraded_gift_colors'] == null
        ? null
        : UpgradedGiftColors.fromJson(
            json['upgraded_gift_colors'] as Map<String, Object?>,
          ),
    profileAccentColorId: ((json['profile_accent_color_id'] as num?) ?? 0)
        .toInt(),
    profileBackgroundCustomEmojiId: int.parse(
      (json['profile_background_custom_emoji_id'] as String?) ?? '0',
    ),
    permissions: json['permissions'] == null
        ? null
        : ChatPermissions.fromJson(json['permissions'] as Map<String, Object?>),
    lastMessage: json['last_message'] == null
        ? null
        : Message.fromJson(json['last_message'] as Map<String, Object?>),
    positions: ((json['positions'] as List?) ?? const [])
        .map((e) => ChatPosition.fromJson(e as Map<String, Object?>))
        .toList(),
    chatLists: ((json['chat_lists'] as List?) ?? const [])
        .map((e) => ChatList.fromJson(e as Map<String, Object?>))
        .toList(),
    messageSenderId: json['message_sender_id'] == null
        ? null
        : MessageSender.fromJson(
            json['message_sender_id'] as Map<String, Object?>,
          ),
    blockList: json['block_list'] == null
        ? null
        : BlockList.fromJson(json['block_list'] as Map<String, Object?>),
    hasProtectedContent: ((json['has_protected_content'] as bool?) ?? false),
    isTranslatable: ((json['is_translatable'] as bool?) ?? false),
    isMarkedAsUnread: ((json['is_marked_as_unread'] as bool?) ?? false),
    viewAsTopics: ((json['view_as_topics'] as bool?) ?? false),
    hasScheduledMessages: ((json['has_scheduled_messages'] as bool?) ?? false),
    hasWelcomeMessages: ((json['has_welcome_messages'] as bool?) ?? false),
    canBeDeletedOnlyForSelf:
        ((json['can_be_deleted_only_for_self'] as bool?) ?? false),
    canBeDeletedForAllUsers:
        ((json['can_be_deleted_for_all_users'] as bool?) ?? false),
    canBeReported: ((json['can_be_reported'] as bool?) ?? false),
    defaultDisableNotification:
        ((json['default_disable_notification'] as bool?) ?? false),
    unreadCount: ((json['unread_count'] as num?) ?? 0).toInt(),
    lastReadInboxMessageId: ((json['last_read_inbox_message_id'] as num?) ?? 0)
        .toInt(),
    lastReadOutboxMessageId:
        ((json['last_read_outbox_message_id'] as num?) ?? 0).toInt(),
    unreadMentionCount: ((json['unread_mention_count'] as num?) ?? 0).toInt(),
    unreadReactionCount: ((json['unread_reaction_count'] as num?) ?? 0).toInt(),
    unreadPollVoteCount: ((json['unread_poll_vote_count'] as num?) ?? 0)
        .toInt(),
    notificationSettings: json['notification_settings'] == null
        ? null
        : ChatNotificationSettings.fromJson(
            json['notification_settings'] as Map<String, Object?>,
          ),
    availableReactions: json['available_reactions'] == null
        ? null
        : ChatAvailableReactions.fromJson(
            json['available_reactions'] as Map<String, Object?>,
          ),
    messageAutoDeleteTime: ((json['message_auto_delete_time'] as num?) ?? 0)
        .toInt(),
    emojiStatus: json['emoji_status'] == null
        ? null
        : EmojiStatus.fromJson(json['emoji_status'] as Map<String, Object?>),
    background: json['background'] == null
        ? null
        : ChatBackground.fromJson(json['background'] as Map<String, Object?>),
    theme: json['theme'] == null
        ? null
        : ChatTheme.fromJson(json['theme'] as Map<String, Object?>),
    actionBar: json['action_bar'] == null
        ? null
        : ChatActionBar.fromJson(json['action_bar'] as Map<String, Object?>),
    businessBotManageBar: json['business_bot_manage_bar'] == null
        ? null
        : BusinessBotManageBar.fromJson(
            json['business_bot_manage_bar'] as Map<String, Object?>,
          ),
    videoChat: json['video_chat'] == null
        ? null
        : VideoChat.fromJson(json['video_chat'] as Map<String, Object?>),
    pendingJoinRequests: json['pending_join_requests'] == null
        ? null
        : ChatJoinRequestsInfo.fromJson(
            json['pending_join_requests'] as Map<String, Object?>,
          ),
    replyMarkupMessageId: ((json['reply_markup_message_id'] as num?) ?? 0)
        .toInt(),
    draftMessage: json['draft_message'] == null
        ? null
        : DraftMessage.fromJson(json['draft_message'] as Map<String, Object?>),
    clientData: ((json['client_data'] as String?) ?? ''),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id,
    'type': type?.toJson(),
    'title': title,
    'photo': photo?.toJson(),
    'accent_color_id': accentColorId,
    'background_custom_emoji_id': backgroundCustomEmojiId.toString(),
    'upgraded_gift_colors': upgradedGiftColors?.toJson(),
    'profile_accent_color_id': profileAccentColorId,
    'profile_background_custom_emoji_id': profileBackgroundCustomEmojiId
        .toString(),
    'permissions': permissions?.toJson(),
    'last_message': lastMessage?.toJson(),
    'positions': positions.map((e) => e.toJson()).toList(),
    'chat_lists': chatLists.map((e) => e.toJson()).toList(),
    'message_sender_id': messageSenderId?.toJson(),
    'block_list': blockList?.toJson(),
    'has_protected_content': hasProtectedContent,
    'is_translatable': isTranslatable,
    'is_marked_as_unread': isMarkedAsUnread,
    'view_as_topics': viewAsTopics,
    'has_scheduled_messages': hasScheduledMessages,
    'has_welcome_messages': hasWelcomeMessages,
    'can_be_deleted_only_for_self': canBeDeletedOnlyForSelf,
    'can_be_deleted_for_all_users': canBeDeletedForAllUsers,
    'can_be_reported': canBeReported,
    'default_disable_notification': defaultDisableNotification,
    'unread_count': unreadCount,
    'last_read_inbox_message_id': lastReadInboxMessageId,
    'last_read_outbox_message_id': lastReadOutboxMessageId,
    'unread_mention_count': unreadMentionCount,
    'unread_reaction_count': unreadReactionCount,
    'unread_poll_vote_count': unreadPollVoteCount,
    'notification_settings': notificationSettings?.toJson(),
    'available_reactions': availableReactions?.toJson(),
    'message_auto_delete_time': messageAutoDeleteTime,
    'emoji_status': emojiStatus?.toJson(),
    'background': background?.toJson(),
    'theme': theme?.toJson(),
    'action_bar': actionBar?.toJson(),
    'business_bot_manage_bar': businessBotManageBar?.toJson(),
    'video_chat': videoChat?.toJson(),
    'pending_join_requests': pendingJoinRequests?.toJson(),
    'reply_markup_message_id': replyMarkupMessageId,
    'draft_message': draftMessage?.toJson(),
    'client_data': clientData,
  };
