/// Contains basic information about another user who started a chat with the current user
final class AccountInfo extends TdObject {
  /// Month when the user was registered in Telegram; 0-12; may be 0 if unknown
  final int registrationMonth;

  /// Year when the user was registered in Telegram; 0-9999; may be 0 if unknown
  final int registrationYear;

  /// A two-letter ISO 3166-1 alpha-2 country code based on the phone number of the user; may be empty if unknown
  final String phoneNumberCountryCode;

  /// Point in time (Unix timestamp) when the user changed name last time; 0 if unknown
  final int lastNameChangeDate;

  /// Point in time (Unix timestamp) when the user changed photo last time; 0 if unknown
  final int lastPhotoChangeDate;

  const AccountInfo({
    required this.registrationMonth,
    required this.registrationYear,
    required this.phoneNumberCountryCode,
    required this.lastNameChangeDate,
    required this.lastPhotoChangeDate,
  });

  static const String constructorType = 'accountInfo';
  @override
  String get tdType => constructorType;

  factory AccountInfo.fromJson(Map<String, Object?> json) => AccountInfo(
    registrationMonth: ((json['registration_month'] as num?) ?? 0).toInt(),
    registrationYear: ((json['registration_year'] as num?) ?? 0).toInt(),
    phoneNumberCountryCode:
        ((json['phone_number_country_code'] as String?) ?? ''),
    lastNameChangeDate: ((json['last_name_change_date'] as num?) ?? 0).toInt(),
    lastPhotoChangeDate: ((json['last_photo_change_date'] as num?) ?? 0)
        .toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'registration_month': registrationMonth,
    'registration_year': registrationYear,
    'phone_number_country_code': phoneNumberCountryCode,
    'last_name_change_date': lastNameChangeDate,
    'last_photo_change_date': lastPhotoChangeDate,
  };
}

/// Describes actions which must be possible to do through a chat action bar
sealed class ChatActionBar extends TdObject {
  const ChatActionBar();

  static ChatActionBar fromJson(
    Map<String, Object?> json,
  ) => switch (json['@type']) {
    'chatActionBarReportSpam' => ChatActionBarReportSpam.fromJson(json),
    'chatActionBarInviteMembers' => ChatActionBarInviteMembers.fromJson(json),
    'chatActionBarReportAddBlock' => ChatActionBarReportAddBlock.fromJson(json),
    'chatActionBarAddContact' => ChatActionBarAddContact.fromJson(json),
    'chatActionBarSharePhoneNumber' => ChatActionBarSharePhoneNumber.fromJson(
      json,
    ),
    'chatActionBarJoinRequest' => ChatActionBarJoinRequest.fromJson(json),
    final t => throw ArgumentError('unknown ChatActionBar constructor: $t'),
  };
}

