/// Represents a single button in an inline keyboard
final class InlineKeyboardButton extends TdObject {
  /// Text of the button
  final String text;

  /// Identifier of the custom emoji that must be shown on the button; 0 if none
  final int iconCustomEmojiId;

  /// Style of the button
  final ButtonStyle? style;

  /// Type of the button
  final InlineKeyboardButtonType? type;

  const InlineKeyboardButton({
    required this.text,
    required this.iconCustomEmojiId,
    this.style,
    this.type,
  });

  static const String constructorType = 'inlineKeyboardButton';
  @override
  String get tdType => constructorType;

  factory InlineKeyboardButton.fromJson(Map<String, Object?> json) =>
      InlineKeyboardButton(
        text: ((json['text'] as String?) ?? ''),
        iconCustomEmojiId: int.parse(
          (json['icon_custom_emoji_id'] as String?) ?? '0',
        ),
        style: json['style'] == null
            ? null
            : ButtonStyle.fromJson(json['style'] as Map<String, Object?>),
        type: json['type'] == null
            ? null
            : InlineKeyboardButtonType.fromJson(
                json['type'] as Map<String, Object?>,
              ),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'text': text,
    'icon_custom_emoji_id': iconCustomEmojiId.toString(),
    'style': style?.toJson(),
    'type': type?.toJson(),
  };
}

/// Contains a description of a custom keyboard and actions that can be done with it to quickly reply to bots
sealed class ReplyMarkup extends TdObject {
  const ReplyMarkup();

  static ReplyMarkup fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'replyMarkupRemoveKeyboard' => ReplyMarkupRemoveKeyboard.fromJson(json),
        'replyMarkupForceReply' => ReplyMarkupForceReply.fromJson(json),
        'replyMarkupShowKeyboard' => ReplyMarkupShowKeyboard.fromJson(json),
        'replyMarkupInlineKeyboard' => ReplyMarkupInlineKeyboard.fromJson(json),
        final t => throw ArgumentError('unknown ReplyMarkup constructor: $t'),
      };
}

/// Instructs application to remove the keyboard once this message has been received. This kind of keyboard can't be received in an incoming message; instead, updateChatReplyMarkup with reply_markup_message == null will be sent
final class ReplyMarkupRemoveKeyboard extends ReplyMarkup {
  /// True, if the keyboard is removed only for the mentioned users or the target user of a reply
  final bool isPersonal;

  const ReplyMarkupRemoveKeyboard({required this.isPersonal});

  static const String constructorType = 'replyMarkupRemoveKeyboard';
  @override
  String get tdType => constructorType;

  factory ReplyMarkupRemoveKeyboard.fromJson(Map<String, Object?> json) =>
      ReplyMarkupRemoveKeyboard(
        isPersonal: ((json['is_personal'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'is_personal': isPersonal,
  };
}

/// Instructs application to force a reply to this message
final class ReplyMarkupForceReply extends ReplyMarkup {
  /// True, if a forced reply must automatically be shown to the current user. For outgoing messages, specify true to show the forced reply only for the mentioned users and for the target user of a reply
  final bool isPersonal;

  /// If non-empty, the placeholder to be shown in the input field when the reply is active; 0-64 characters
  final String inputFieldPlaceholder;

  const ReplyMarkupForceReply({
    required this.isPersonal,
    required this.inputFieldPlaceholder,
  });

  static const String constructorType = 'replyMarkupForceReply';
  @override
