/// Information about the OAuth authorization
final class OauthLinkInfo extends TdObject {
  /// Identifier of the user for which the link was generated; may be 0 if unknown. The corresponding user may be unknown. If the user is logged in the application, then they must be chosen for authorization by default
  final int userId;

  /// An HTTP URL where the user authorizes
  final String url;

  /// A domain of the URL
  final String domain;

  /// True, if the authorization originates from an application
  final bool fromApp;

  /// Verified name of the application; if empty, then "Unverified App" must be shown instead
  final String verifiedAppName;

  /// User identifier of a bot linked with the website
  final int botUserId;

  /// True, if the user must be asked for the permission to the bot to send them messages
  final bool requestWriteAccess;

  /// True, if the user must be asked for the permission to share their phone number
  final bool requestPhoneNumberAccess;

  /// The version of a browser used for the authorization
  final String browser;

  /// Operating system the browser is running on
  final String platform;

  /// IP address from which the authorization is performed, in human-readable format
  final String ipAddress;

  /// Human-readable description of a country and a region from which the authorization is performed, based on the IP address
  final String location;

  /// True, if code matching dialog must be shown first and checkOauthRequestMatchCode must be called before acceptOauthRequest. Otherwise, checkOauthRequestMatchCode must not be called
  final bool matchCodeFirst;

  /// The list of codes to match; may be empty if irrelevant
  final List<String> matchCodes;

  const OauthLinkInfo({
    required this.userId,
    required this.url,
    required this.domain,
    required this.fromApp,
    required this.verifiedAppName,
    required this.botUserId,
    required this.requestWriteAccess,
    required this.requestPhoneNumberAccess,
    required this.browser,
    required this.platform,
    required this.ipAddress,
    required this.location,
    required this.matchCodeFirst,
    required this.matchCodes,
  });

  static const String constructorType = 'oauthLinkInfo';
  @override
  String get tdType => constructorType;

  factory OauthLinkInfo.fromJson(Map<String, Object?> json) => OauthLinkInfo(
    userId: ((json['user_id'] as num?) ?? 0).toInt(),
    url: ((json['url'] as String?) ?? ''),
    domain: ((json['domain'] as String?) ?? ''),
    fromApp: ((json['from_app'] as bool?) ?? false),
    verifiedAppName: ((json['verified_app_name'] as String?) ?? ''),
    botUserId: ((json['bot_user_id'] as num?) ?? 0).toInt(),
    requestWriteAccess: ((json['request_write_access'] as bool?) ?? false),
    requestPhoneNumberAccess:
        ((json['request_phone_number_access'] as bool?) ?? false),
    browser: ((json['browser'] as String?) ?? ''),
    platform: ((json['platform'] as String?) ?? ''),
    ipAddress: ((json['ip_address'] as String?) ?? ''),
    location: ((json['location'] as String?) ?? ''),
    matchCodeFirst: ((json['match_code_first'] as bool?) ?? false),
    matchCodes: ((json['match_codes'] as List?) ?? const [])
        .map((e) => ((e as String?) ?? ''))
        .toList(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'user_id': userId,
    'url': url,
    'domain': domain,
    'from_app': fromApp,
    'verified_app_name': verifiedAppName,
    'bot_user_id': botUserId,
    'request_write_access': requestWriteAccess,
    'request_phone_number_access': requestPhoneNumberAccess,
    'browser': browser,
    'platform': platform,
    'ip_address': ipAddress,
    'location': location,
    'match_code_first': matchCodeFirst,
    'match_codes': matchCodes.map((e) => e).toList(),
  };
}

/// Contains information about a message thread
final class MessageThreadInfo extends TdObject {
  /// Identifier of the chat to which the message thread belongs
  final int chatId;

  /// Message thread identifier, unique within the chat
  final int messageThreadId;

  /// Information about the message thread; may be null for forum topic threads
  final MessageReplyInfo? replyInfo;

  /// Approximate number of unread messages in the message thread
  final int unreadMessageCount;

  /// The messages from which the thread starts. The messages are returned in reverse chronological order (i.e., in order of decreasing message_id)
  final List<Message> messages;

  /// A draft of a message in the message thread; may be null if none
  final DraftMessage? draftMessage;

  const MessageThreadInfo({
    required this.chatId,
    required this.messageThreadId,
    this.replyInfo,
    required this.unreadMessageCount,
    required this.messages,
    this.draftMessage,
  });

  static const String constructorType = 'messageThreadInfo';
  @override
  String get tdType => constructorType;

  factory MessageThreadInfo.fromJson(
    Map<String, Object?> json,
  ) => MessageThreadInfo(
    chatId: ((json['chat_id'] as num?) ?? 0).toInt(),
    messageThreadId: ((json['message_thread_id'] as num?) ?? 0).toInt(),
    replyInfo: json['reply_info'] == null
        ? null
        : MessageReplyInfo.fromJson(json['reply_info'] as Map<String, Object?>),
    unreadMessageCount: ((json['unread_message_count'] as num?) ?? 0).toInt(),
    messages: ((json['messages'] as List?) ?? const [])
        .map((e) => Message.fromJson(e as Map<String, Object?>))
        .toList(),
    draftMessage: json['draft_message'] == null
        ? null
        : DraftMessage.fromJson(json['draft_message'] as Map<String, Object?>),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'chat_id': chatId,
    'message_thread_id': messageThreadId,
    'reply_info': replyInfo?.toJson(),
    'unread_message_count': unreadMessageCount,
    'messages': messages.map((e) => e.toJson()).toList(),
    'draft_message': draftMessage?.toJson(),
  };
}

