  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id,
    'type': type?.toJson(),
    'is_pinned': isPinned,
    'order': order.toString(),
    'last_message': lastMessage?.toJson(),
    'draft_message': draftMessage?.toJson(),
  };
}

/// Contains information about a topic in a channel direct messages chat administered by the current user
final class DirectMessagesChatTopic extends TdObject {
  /// Identifier of the chat to which the topic belongs
  final int chatId;

  /// Unique topic identifier
  final int id;

  /// Identifier of the user or chat that sends the messages to the topic
  final MessageSender? senderId;

  /// A parameter used to determine order of the topic in the topic list. Topics must be sorted by the order in descending order
  final int order;

  /// True, if the other party can send unpaid messages even if the chat has paid messages enabled
  final bool canSendUnpaidMessages;

  /// True, if the topic is marked as unread
  final bool isMarkedAsUnread;

  /// Number of unread messages in the chat
  final int unreadCount;

  /// Identifier of the last read incoming message
  final int lastReadInboxMessageId;

  /// Identifier of the last read outgoing message
  final int lastReadOutboxMessageId;

  /// Number of messages with unread reactions in the chat
  final int unreadReactionCount;

  /// Last message in the topic; may be null if none or unknown
  final Message? lastMessage;

  /// A draft of a message in the topic; may be null if none
  final DraftMessage? draftMessage;

  const DirectMessagesChatTopic({
    required this.chatId,
    required this.id,
    this.senderId,
    required this.order,
    required this.canSendUnpaidMessages,
    required this.isMarkedAsUnread,
    required this.unreadCount,
    required this.lastReadInboxMessageId,
    required this.lastReadOutboxMessageId,
    required this.unreadReactionCount,
    this.lastMessage,
    this.draftMessage,
  });

  static const String constructorType = 'directMessagesChatTopic';
  @override
  String get tdType => constructorType;

  factory DirectMessagesChatTopic.fromJson(
    Map<String, Object?> json,
  ) => DirectMessagesChatTopic(
    chatId: ((json['chat_id'] as num?) ?? 0).toInt(),
    id: ((json['id'] as num?) ?? 0).toInt(),
    senderId: json['sender_id'] == null
        ? null
        : MessageSender.fromJson(json['sender_id'] as Map<String, Object?>),
    order: int.parse((json['order'] as String?) ?? '0'),
    canSendUnpaidMessages:
        ((json['can_send_unpaid_messages'] as bool?) ?? false),
    isMarkedAsUnread: ((json['is_marked_as_unread'] as bool?) ?? false),
    unreadCount: ((json['unread_count'] as num?) ?? 0).toInt(),
    lastReadInboxMessageId: ((json['last_read_inbox_message_id'] as num?) ?? 0)
        .toInt(),
    lastReadOutboxMessageId:
        ((json['last_read_outbox_message_id'] as num?) ?? 0).toInt(),
    unreadReactionCount: ((json['unread_reaction_count'] as num?) ?? 0).toInt(),
    lastMessage: json['last_message'] == null
        ? null
        : Message.fromJson(json['last_message'] as Map<String, Object?>),
    draftMessage: json['draft_message'] == null
        ? null
        : DraftMessage.fromJson(json['draft_message'] as Map<String, Object?>),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'chat_id': chatId,
    'id': id,
    'sender_id': senderId?.toJson(),
    'order': order.toString(),
    'can_send_unpaid_messages': canSendUnpaidMessages,
    'is_marked_as_unread': isMarkedAsUnread,
    'unread_count': unreadCount,
    'last_read_inbox_message_id': lastReadInboxMessageId,
    'last_read_outbox_message_id': lastReadOutboxMessageId,
    'unread_reaction_count': unreadReactionCount,
    'last_message': lastMessage?.toJson(),
    'draft_message': draftMessage?.toJson(),
  };
}

