    required this.forumTopicId,
    required this.name,
    this.icon,
    required this.creationDate,
    this.creatorId,
    required this.isGeneral,
    required this.isOutgoing,
    required this.isClosed,
    required this.isHidden,
    required this.isNameImplicit,
  });

  static const String constructorType = 'forumTopicInfo';
  @override
  String get tdType => constructorType;

  factory ForumTopicInfo.fromJson(Map<String, Object?> json) => ForumTopicInfo(
    chatId: ((json['chat_id'] as num?) ?? 0).toInt(),
    forumTopicId: ((json['forum_topic_id'] as num?) ?? 0).toInt(),
    name: ((json['name'] as String?) ?? ''),
    icon: json['icon'] == null
        ? null
        : ForumTopicIcon.fromJson(json['icon'] as Map<String, Object?>),
    creationDate: ((json['creation_date'] as num?) ?? 0).toInt(),
    creatorId: json['creator_id'] == null
        ? null
        : MessageSender.fromJson(json['creator_id'] as Map<String, Object?>),
    isGeneral: ((json['is_general'] as bool?) ?? false),
    isOutgoing: ((json['is_outgoing'] as bool?) ?? false),
    isClosed: ((json['is_closed'] as bool?) ?? false),
    isHidden: ((json['is_hidden'] as bool?) ?? false),
    isNameImplicit: ((json['is_name_implicit'] as bool?) ?? false),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'chat_id': chatId,
    'forum_topic_id': forumTopicId,
    'name': name,
    'icon': icon?.toJson(),
    'creation_date': creationDate,
    'creator_id': creatorId?.toJson(),
    'is_general': isGeneral,
    'is_outgoing': isOutgoing,
    'is_closed': isClosed,
    'is_hidden': isHidden,
    'is_name_implicit': isNameImplicit,
  };
}

/// Describes a forum topic
final class ForumTopic extends TdObject {
  /// Basic information about the topic
  final ForumTopicInfo? info;

  /// Last message in the topic; may be null if unknown
  final Message? lastMessage;

  /// A parameter used to determine order of the topic in the topic list. Topics must be sorted by the order in descending order
  final int order;

  /// True, if the topic is pinned in the topic list
  final bool isPinned;

  /// Number of unread messages in the topic
  final int unreadCount;

  /// Identifier of the last read incoming message
  final int lastReadInboxMessageId;

  /// Identifier of the last read outgoing message
  final int lastReadOutboxMessageId;

  /// Number of unread messages with a mention/reply in the topic
  final int unreadMentionCount;

  /// Number of messages with unread reactions in the topic
  final int unreadReactionCount;

  /// Number of messages with unread poll votes in the topic
  final int unreadPollVoteCount;

  /// Notification settings for the topic
  final ChatNotificationSettings? notificationSettings;

  /// A draft of a message in the topic; may be null if none
  final DraftMessage? draftMessage;

  const ForumTopic({
    this.info,
    this.lastMessage,
    required this.order,
    required this.isPinned,
    required this.unreadCount,
    required this.lastReadInboxMessageId,
    required this.lastReadOutboxMessageId,
    required this.unreadMentionCount,
    required this.unreadReactionCount,
    required this.unreadPollVoteCount,
    this.notificationSettings,
    this.draftMessage,
  });

  static const String constructorType = 'forumTopic';
  @override
  String get tdType => constructorType;

  factory ForumTopic.fromJson(Map<String, Object?> json) => ForumTopic(
    info: json['info'] == null
        ? null
        : ForumTopicInfo.fromJson(json['info'] as Map<String, Object?>),
    lastMessage: json['last_message'] == null
        ? null
        : Message.fromJson(json['last_message'] as Map<String, Object?>),
    order: int.parse((json['order'] as String?) ?? '0'),
    isPinned: ((json['is_pinned'] as bool?) ?? false),
    unreadCount: ((json['unread_count'] as num?) ?? 0).toInt(),
    lastReadInboxMessageId: ((json['last_read_inbox_message_id'] as num?) ?? 0)
        .toInt(),
    lastReadOutboxMessageId:
        ((json['last_read_outbox_message_id'] as num?) ?? 0).toInt(),
    unreadMentionCount: ((json['unread_mention_count'] as num?) ?? 0).toInt(),
    unreadReactionCount: ((json['unread_reaction_count'] as num?) ?? 0).toInt(),
    unreadPollVoteCount: ((json['unread_poll_vote_count'] as num?) ?? 0)
        .toInt(),
    notificationSettings: json['notification_settings'] == null
        ? null
        : ChatNotificationSettings.fromJson(
            json['notification_settings'] as Map<String, Object?>,
          ),
    draftMessage: json['draft_message'] == null
        ? null
        : DraftMessage.fromJson(json['draft_message'] as Map<String, Object?>),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'info': info?.toJson(),
    'last_message': lastMessage?.toJson(),
    'order': order.toString(),
    'is_pinned': isPinned,
    'unread_count': unreadCount,
    'last_read_inbox_message_id': lastReadInboxMessageId,
    'last_read_outbox_message_id': lastReadOutboxMessageId,
    'unread_mention_count': unreadMentionCount,
    'unread_reaction_count': unreadReactionCount,
    'unread_poll_vote_count': unreadPollVoteCount,
    'notification_settings': notificationSettings?.toJson(),
    'draft_message': draftMessage?.toJson(),
  };
}

/// Describes a list of forum topics
final class ForumTopics extends TdObject {
