  /// Offset message identifier for the next getForumTopics request
  final int nextOffsetMessageId;

  /// Offset forum topic identifier for the next getForumTopics request
  final int nextOffsetForumTopicId;

  const ForumTopics({
    required this.totalCount,
    required this.topics,
    required this.nextOffsetDate,
    required this.nextOffsetMessageId,
    required this.nextOffsetForumTopicId,
  });

  static const String constructorType = 'forumTopics';
  @override
  String get tdType => constructorType;

  factory ForumTopics.fromJson(Map<String, Object?> json) => ForumTopics(
    totalCount: ((json['total_count'] as num?) ?? 0).toInt(),
    topics: ((json['topics'] as List?) ?? const [])
        .map((e) => ForumTopic.fromJson(e as Map<String, Object?>))
        .toList(),
    nextOffsetDate: ((json['next_offset_date'] as num?) ?? 0).toInt(),
    nextOffsetMessageId: ((json['next_offset_message_id'] as num?) ?? 0)
        .toInt(),
    nextOffsetForumTopicId: ((json['next_offset_forum_topic_id'] as num?) ?? 0)
        .toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'total_count': totalCount,
    'topics': topics.map((e) => e.toJson()).toList(),
    'next_offset_date': nextOffsetDate,
    'next_offset_message_id': nextOffsetMessageId,
    'next_offset_forum_topic_id': nextOffsetForumTopicId,
  };
}

