  /// Text
  final RichText? text;

  /// The hashtag
  final String hashtag;

  const RichTextHashtag({this.text, required this.hashtag});

  static const String constructorType = 'richTextHashtag';
  @override
  String get tdType => constructorType;

  factory RichTextHashtag.fromJson(Map<String, Object?> json) =>
      RichTextHashtag(
        text: json['text'] == null
            ? null
            : RichText.fromJson(json['text'] as Map<String, Object?>),
        hashtag: ((json['hashtag'] as String?) ?? ''),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'text': text?.toJson(),
    'hashtag': hashtag,
  };
}

