/// Describes a horizontal alignment of a table cell content
sealed class PageBlockHorizontalAlignment extends TdObject {
  const PageBlockHorizontalAlignment();

  static PageBlockHorizontalAlignment fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'pageBlockHorizontalAlignmentLeft' =>
          PageBlockHorizontalAlignmentLeft.fromJson(json),
        'pageBlockHorizontalAlignmentCenter' =>
          PageBlockHorizontalAlignmentCenter.fromJson(json),
        'pageBlockHorizontalAlignmentRight' =>
          PageBlockHorizontalAlignmentRight.fromJson(json),
        final t => throw ArgumentError(
          'unknown PageBlockHorizontalAlignment constructor: $t',
        ),
      };
}

