/// Represents a cell of a table
final class PageBlockTableCell extends TdObject {
  /// Cell text; may be null. If the text is null, then the cell must be invisible
  final RichText? text;

  /// True, if it is a header cell
  final bool isHeader;

  /// The number of columns the cell spans
  final int colspan;

  /// The number of rows the cell spans
  final int rowspan;

  /// Horizontal cell content alignment
  final PageBlockHorizontalAlignment? align;

  /// Vertical cell content alignment
  final PageBlockVerticalAlignment? valign;

  const PageBlockTableCell({
    this.text,
    required this.isHeader,
    required this.colspan,
    required this.rowspan,
    this.align,
    this.valign,
  });

  static const String constructorType = 'pageBlockTableCell';
  @override
  String get tdType => constructorType;

  factory PageBlockTableCell.fromJson(Map<String, Object?> json) =>
      PageBlockTableCell(
        text: json['text'] == null
            ? null
            : RichText.fromJson(json['text'] as Map<String, Object?>),
        isHeader: ((json['is_header'] as bool?) ?? false),
        colspan: ((json['colspan'] as num?) ?? 0).toInt(),
        rowspan: ((json['rowspan'] as num?) ?? 0).toInt(),
        align: json['align'] == null
            ? null
            : PageBlockHorizontalAlignment.fromJson(
                json['align'] as Map<String, Object?>,
              ),
        valign: json['valign'] == null
            ? null
            : PageBlockVerticalAlignment.fromJson(
                json['valign'] as Map<String, Object?>,
              ),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'text': text?.toJson(),
    'is_header': isHeader,
    'colspan': colspan,
    'rowspan': rowspan,
    'align': align?.toJson(),
    'valign': valign?.toJson(),
  };
}

/// Contains information about a related article
final class PageBlockRelatedArticle extends TdObject {
  /// Related article URL
  final String url;

  /// Article title; may be empty
  final String title;

  /// Article description; may be empty
  final String description;

  /// Article photo; may be null
  final Photo? photo;

  /// Article author; may be empty
  final String author;

  /// Point in time (Unix timestamp) when the article was published; 0 if unknown
  final int publishDate;

  const PageBlockRelatedArticle({
    required this.url,
    required this.title,
    required this.description,
    this.photo,
    required this.author,
    required this.publishDate,
  });

  static const String constructorType = 'pageBlockRelatedArticle';
  @override
  String get tdType => constructorType;

  factory PageBlockRelatedArticle.fromJson(Map<String, Object?> json) =>
      PageBlockRelatedArticle(
        url: ((json['url'] as String?) ?? ''),
        title: ((json['title'] as String?) ?? ''),
        description: ((json['description'] as String?) ?? ''),
        photo: json['photo'] == null
            ? null
