/// Describes a block of an instant view for a web page or a block of a rich message
sealed class PageBlock extends TdObject {
  const PageBlock();

  static PageBlock fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'pageBlockTitle' => PageBlockTitle.fromJson(json),
        'pageBlockSubtitle' => PageBlockSubtitle.fromJson(json),
        'pageBlockAuthorDate' => PageBlockAuthorDate.fromJson(json),
        'pageBlockHeader' => PageBlockHeader.fromJson(json),
        'pageBlockSubheader' => PageBlockSubheader.fromJson(json),
        'pageBlockSectionHeading' => PageBlockSectionHeading.fromJson(json),
        'pageBlockKicker' => PageBlockKicker.fromJson(json),
        'pageBlockParagraph' => PageBlockParagraph.fromJson(json),
        'pageBlockPreformatted' => PageBlockPreformatted.fromJson(json),
        'pageBlockFooter' => PageBlockFooter.fromJson(json),
        'pageBlockThinking' => PageBlockThinking.fromJson(json),
        'pageBlockDivider' => PageBlockDivider.fromJson(json),
        'pageBlockMathematicalExpression' =>
          PageBlockMathematicalExpression.fromJson(json),
        'pageBlockAnchor' => PageBlockAnchor.fromJson(json),
        'pageBlockList' => PageBlockList.fromJson(json),
        'pageBlockBlockQuote' => PageBlockBlockQuote.fromJson(json),
        'pageBlockExpandableBlockQuote' =>
          PageBlockExpandableBlockQuote.fromJson(json),
        'pageBlockPullQuote' => PageBlockPullQuote.fromJson(json),
        'pageBlockAnimation' => PageBlockAnimation.fromJson(json),
        'pageBlockAudio' => PageBlockAudio.fromJson(json),
        'pageBlockDocument' => PageBlockDocument.fromJson(json),
        'pageBlockPhoto' => PageBlockPhoto.fromJson(json),
        'pageBlockVideo' => PageBlockVideo.fromJson(json),
        'pageBlockVoiceNote' => PageBlockVoiceNote.fromJson(json),
        'pageBlockCover' => PageBlockCover.fromJson(json),
        'pageBlockEmbedded' => PageBlockEmbedded.fromJson(json),
        'pageBlockEmbeddedPost' => PageBlockEmbeddedPost.fromJson(json),
        'pageBlockCollage' => PageBlockCollage.fromJson(json),
        'pageBlockSlideshow' => PageBlockSlideshow.fromJson(json),
        'pageBlockChatLink' => PageBlockChatLink.fromJson(json),
        'pageBlockTable' => PageBlockTable.fromJson(json),
        'pageBlockDetails' => PageBlockDetails.fromJson(json),
        'pageBlockRelatedArticles' => PageBlockRelatedArticles.fromJson(json),
        'pageBlockMap' => PageBlockMap.fromJson(json),
        'pageBlockButtonRow' => PageBlockButtonRow.fromJson(json),
        'pageBlockUnsupported' => PageBlockUnsupported.fromJson(json),
        final t => throw ArgumentError('unknown PageBlock constructor: $t'),
      };
}

