/// Describes type of payment form
sealed class PaymentFormType extends TdObject {
  const PaymentFormType();

  static PaymentFormType fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'paymentFormTypeRegular' => PaymentFormTypeRegular.fromJson(json),
        'paymentFormTypeStars' => PaymentFormTypeStars.fromJson(json),
        'paymentFormTypeStarSubscription' =>
          PaymentFormTypeStarSubscription.fromJson(json),
        final t => throw ArgumentError(
          'unknown PaymentFormType constructor: $t',
        ),
      };
}

/// The payment form is for a regular payment
final class PaymentFormTypeRegular extends PaymentFormType {
  /// Full information about the invoice
  final Invoice? invoice;

  /// User identifier of the payment provider bot
  final int paymentProviderUserId;

  /// Information about the payment provider
  final PaymentProvider? paymentProvider;

  /// The list of additional payment options
  final List<PaymentOption> additionalPaymentOptions;

  /// Saved server-side order information; may be null
  final OrderInfo? savedOrderInfo;

  /// The list of saved payment credentials
  final List<SavedCredentials> savedCredentials;

  /// True, if the user can choose to save credentials
  final bool canSaveCredentials;

  /// True, if the user will be able to save credentials, if sets up a 2-step verification password
  final bool needPassword;

  const PaymentFormTypeRegular({
    this.invoice,
    required this.paymentProviderUserId,
    this.paymentProvider,
    required this.additionalPaymentOptions,
    this.savedOrderInfo,
    required this.savedCredentials,
    required this.canSaveCredentials,
    required this.needPassword,
  });

  static const String constructorType = 'paymentFormTypeRegular';
  @override
  String get tdType => constructorType;

  factory PaymentFormTypeRegular.fromJson(Map<String, Object?> json) =>
      PaymentFormTypeRegular(
        invoice: json['invoice'] == null
            ? null
            : Invoice.fromJson(json['invoice'] as Map<String, Object?>),
        paymentProviderUserId: ((json['payment_provider_user_id'] as num?) ?? 0)
            .toInt(),
        paymentProvider: json['payment_provider'] == null
            ? null
            : PaymentProvider.fromJson(
                json['payment_provider'] as Map<String, Object?>,
              ),
        additionalPaymentOptions:
            ((json['additional_payment_options'] as List?) ?? const [])
                .map((e) => PaymentOption.fromJson(e as Map<String, Object?>))
                .toList(),
        savedOrderInfo: json['saved_order_info'] == null
            ? null
            : OrderInfo.fromJson(
                json['saved_order_info'] as Map<String, Object?>,
              ),
        savedCredentials: ((json['saved_credentials'] as List?) ?? const [])
            .map((e) => SavedCredentials.fromJson(e as Map<String, Object?>))
            .toList(),
        canSaveCredentials: ((json['can_save_credentials'] as bool?) ?? false),
        needPassword: ((json['need_password'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'invoice': invoice?.toJson(),
    'payment_provider_user_id': paymentProviderUserId,
    'payment_provider': paymentProvider?.toJson(),
    'additional_payment_options': additionalPaymentOptions
        .map((e) => e.toJson())
        .toList(),
    'saved_order_info': savedOrderInfo?.toJson(),
    'saved_credentials': savedCredentials.map((e) => e.toJson()).toList(),
    'can_save_credentials': canSaveCredentials,
    'need_password': needPassword,
  };
}

