/// Represents a date according to the Gregorian calendar
final class Date extends TdObject {
  /// Day of the month; 1-31
  final int day;

  /// Month; 1-12
  final int month;

  /// Year; 1-9999
  final int year;

  const Date({required this.day, required this.month, required this.year});

  static const String constructorType = 'date';
  @override
  String get tdType => constructorType;

  factory Date.fromJson(Map<String, Object?> json) => Date(
    day: ((json['day'] as num?) ?? 0).toInt(),
    month: ((json['month'] as num?) ?? 0).toInt(),
    year: ((json['year'] as num?) ?? 0).toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'day': day,
    'month': month,
    'year': year,
  };
}

/// Contains the user's personal details
final class PersonalDetails extends TdObject {
  /// First name of the user written in English; 1-255 characters
  final String firstName;

  /// Middle name of the user written in English; 0-255 characters
  final String middleName;

  /// Last name of the user written in English; 1-255 characters
  final String lastName;

  /// Native first name of the user; 1-255 characters
  final String nativeFirstName;

  /// Native middle name of the user; 0-255 characters
  final String nativeMiddleName;

  /// Native last name of the user; 1-255 characters
  final String nativeLastName;

  /// Birthdate of the user
  final Date? birthdate;

  /// Gender of the user, "male" or "female"
  final String gender;

  /// A two-letter ISO 3166-1 alpha-2 country code of the user's country
  final String countryCode;

  /// A two-letter ISO 3166-1 alpha-2 country code of the user's residence country
  final String residenceCountryCode;

  const PersonalDetails({
    required this.firstName,
    required this.middleName,
    required this.lastName,
    required this.nativeFirstName,
    required this.nativeMiddleName,
    required this.nativeLastName,
    this.birthdate,
    required this.gender,
    required this.countryCode,
    required this.residenceCountryCode,
  });

  static const String constructorType = 'personalDetails';
  @override
  String get tdType => constructorType;

  factory PersonalDetails.fromJson(Map<String, Object?> json) =>
      PersonalDetails(
        firstName: ((json['first_name'] as String?) ?? ''),
        middleName: ((json['middle_name'] as String?) ?? ''),
        lastName: ((json['last_name'] as String?) ?? ''),
        nativeFirstName: ((json['native_first_name'] as String?) ?? ''),
        nativeMiddleName: ((json['native_middle_name'] as String?) ?? ''),
        nativeLastName: ((json['native_last_name'] as String?) ?? ''),
        birthdate: json['birthdate'] == null
            ? null
            : Date.fromJson(json['birthdate'] as Map<String, Object?>),
        gender: ((json['gender'] as String?) ?? ''),
        countryCode: ((json['country_code'] as String?) ?? ''),
        residenceCountryCode:
            ((json['residence_country_code'] as String?) ?? ''),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'first_name': firstName,
    'middle_name': middleName,
    'last_name': lastName,
    'native_first_name': nativeFirstName,
    'native_middle_name': nativeMiddleName,
    'native_last_name': nativeLastName,
    'birthdate': birthdate?.toJson(),
    'gender': gender,
    'country_code': countryCode,
    'residence_country_code': residenceCountryCode,
  };
}

/// An identity document
final class IdentityDocument extends TdObject {
  /// Document number; 1-24 characters
  final String number;

  /// Document expiration date; may be null if not applicable
  final Date? expirationDate;

  /// Front side of the document
  final DatedFile? frontSide;

  /// Reverse side of the document; only for driver license and identity card; may be null
  final DatedFile? reverseSide;

  /// Selfie with the document; may be null
  final DatedFile? selfie;

  /// List of files containing a certified English translation of the document
  final List<DatedFile> translation;

  const IdentityDocument({
    required this.number,
    this.expirationDate,
    this.frontSide,
    this.reverseSide,
    this.selfie,
    required this.translation,
  });

  static const String constructorType = 'identityDocument';
  @override
  String get tdType => constructorType;

  factory IdentityDocument.fromJson(Map<String, Object?> json) =>
      IdentityDocument(
        number: ((json['number'] as String?) ?? ''),
        expirationDate: json['expiration_date'] == null
            ? null
            : Date.fromJson(json['expiration_date'] as Map<String, Object?>),
        frontSide: json['front_side'] == null
            ? null
            : DatedFile.fromJson(json['front_side'] as Map<String, Object?>),
        reverseSide: json['reverse_side'] == null
            ? null
            : DatedFile.fromJson(json['reverse_side'] as Map<String, Object?>),
        selfie: json['selfie'] == null
            ? null
            : DatedFile.fromJson(json['selfie'] as Map<String, Object?>),
        translation: ((json['translation'] as List?) ?? const [])
            .map((e) => DatedFile.fromJson(e as Map<String, Object?>))
            .toList(),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'number': number,
    'expiration_date': expirationDate?.toJson(),
    'front_side': frontSide?.toJson(),
    'reverse_side': reverseSide?.toJson(),
    'selfie': selfie?.toJson(),
    'translation': translation.map((e) => e.toJson()).toList(),
  };
}

