/// Describes precision with which to show a date or a time
sealed class DateTimePartPrecision extends TdObject {
  const DateTimePartPrecision();

  static DateTimePartPrecision fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'dateTimePartPrecisionNone' => DateTimePartPrecisionNone.fromJson(json),
        'dateTimePartPrecisionShort' => DateTimePartPrecisionShort.fromJson(
          json,
        ),
        'dateTimePartPrecisionLong' => DateTimePartPrecisionLong.fromJson(json),
        final t => throw ArgumentError(
          'unknown DateTimePartPrecision constructor: $t',
        ),
      };
}

