      DateTimeFormattingTypeRelative();

  @override
  Map<String, Object?> toJson() => {'@type': constructorType};
}

/// The date and time must be shown as absolute timestamps
final class DateTimeFormattingTypeAbsolute extends DateTimeFormattingType {
  /// The precision with which hours, minutes and seconds are shown
  final DateTimePartPrecision? timePrecision;

  /// The precision with which the date is shown
  final DateTimePartPrecision? datePrecision;

  /// True, if the day of week must be shown
  final bool showDayOfWeek;

  const DateTimeFormattingTypeAbsolute({
    this.timePrecision,
    this.datePrecision,
    required this.showDayOfWeek,
  });

  static const String constructorType = 'dateTimeFormattingTypeAbsolute';
  @override
  String get tdType => constructorType;

  factory DateTimeFormattingTypeAbsolute.fromJson(Map<String, Object?> json) =>
      DateTimeFormattingTypeAbsolute(
        timePrecision: json['time_precision'] == null
            ? null
            : DateTimePartPrecision.fromJson(
                json['time_precision'] as Map<String, Object?>,
              ),
        datePrecision: json['date_precision'] == null
            ? null
            : DateTimePartPrecision.fromJson(
                json['date_precision'] as Map<String, Object?>,
              ),
        showDayOfWeek: ((json['show_day_of_week'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'time_precision': timePrecision?.toJson(),
    'date_precision': datePrecision?.toJson(),
    'show_day_of_week': showDayOfWeek,
  };
}

/// Represents a part of the text which must be formatted differently
sealed class TextEntityType extends TdObject {
  const TextEntityType();

  static TextEntityType fromJson(
    Map<String, Object?> json,
  ) => switch (json['@type']) {
    'textEntityTypeMention' => TextEntityTypeMention.fromJson(json),
    'textEntityTypeHashtag' => TextEntityTypeHashtag.fromJson(json),
    'textEntityTypeCashtag' => TextEntityTypeCashtag.fromJson(json),
    'textEntityTypeBotCommand' => TextEntityTypeBotCommand.fromJson(json),
    'textEntityTypeUrl' => TextEntityTypeUrl.fromJson(json),
    'textEntityTypeEmailAddress' => TextEntityTypeEmailAddress.fromJson(json),
    'textEntityTypePhoneNumber' => TextEntityTypePhoneNumber.fromJson(json),
    'textEntityTypeBankCardNumber' => TextEntityTypeBankCardNumber.fromJson(
      json,
    ),
    'textEntityTypeBold' => TextEntityTypeBold.fromJson(json),
    'textEntityTypeItalic' => TextEntityTypeItalic.fromJson(json),
    'textEntityTypeUnderline' => TextEntityTypeUnderline.fromJson(json),
    'textEntityTypeStrikethrough' => TextEntityTypeStrikethrough.fromJson(json),
    'textEntityTypeSpoiler' => TextEntityTypeSpoiler.fromJson(json),
    'textEntityTypeCode' => TextEntityTypeCode.fromJson(json),
    'textEntityTypePre' => TextEntityTypePre.fromJson(json),
    'textEntityTypePreCode' => TextEntityTypePreCode.fromJson(json),
    'textEntityTypeBlockQuote' => TextEntityTypeBlockQuote.fromJson(json),
    'textEntityTypeExpandableBlockQuote' =>
      TextEntityTypeExpandableBlockQuote.fromJson(json),
    'textEntityTypeTextUrl' => TextEntityTypeTextUrl.fromJson(json),
    'textEntityTypeMentionName' => TextEntityTypeMentionName.fromJson(json),
    'textEntityTypeCustomEmoji' => TextEntityTypeCustomEmoji.fromJson(json),
    'textEntityTypeMediaTimestamp' => TextEntityTypeMediaTimestamp.fromJson(
      json,
    ),
    'textEntityTypeDateTime' => TextEntityTypeDateTime.fromJson(json),
    final t => throw ArgumentError('unknown TextEntityType constructor: $t'),
  };
}

