/// A thumbnail to be sent along with a file; must be in JPEG or WEBP format for stickers, and less than 200 KB in size
final class InputThumbnail extends TdObject {
  /// Thumbnail file to send. Sending thumbnails by file_id is currently not supported
  final InputFile? thumbnail;

  /// Thumbnail width, usually shouldn't exceed 320. Use 0 if unknown
  final int width;

  /// Thumbnail height, usually shouldn't exceed 320. Use 0 if unknown
  final int height;

  const InputThumbnail({
    this.thumbnail,
    required this.width,
    required this.height,
  });

  static const String constructorType = 'inputThumbnail';
  @override
  String get tdType => constructorType;

  factory InputThumbnail.fromJson(Map<String, Object?> json) => InputThumbnail(
    thumbnail: json['thumbnail'] == null
        ? null
        : InputFile.fromJson(json['thumbnail'] as Map<String, Object?>),
    width: ((json['width'] as num?) ?? 0).toInt(),
    height: ((json['height'] as num?) ?? 0).toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'thumbnail': thumbnail?.toJson(),
    'width': width,
    'height': height,
  };
}

/// An animation to be sent
final class InputAnimation extends TdObject {
