        : InputFile.fromJson(json['photo'] as Map<String, Object?>),
    thumbnail: json['thumbnail'] == null
        ? null
        : InputThumbnail.fromJson(json['thumbnail'] as Map<String, Object?>),
    video: json['video'] == null
        ? null
        : InputFile.fromJson(json['video'] as Map<String, Object?>),
    addedStickerFileIds: ((json['added_sticker_file_ids'] as List?) ?? const [])
        .map((e) => ((e as num?) ?? 0).toInt())
        .toList(),
    width: ((json['width'] as num?) ?? 0).toInt(),
    height: ((json['height'] as num?) ?? 0).toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'photo': photo?.toJson(),
    'thumbnail': thumbnail?.toJson(),
    'video': video?.toJson(),
    'added_sticker_file_ids': addedStickerFileIds.map((e) => e).toList(),
    'width': width,
    'height': height,
  };
}

