/// Describes a block of a rich message to send
sealed class InputPageBlock extends TdObject {
  const InputPageBlock();

  static InputPageBlock fromJson(
    Map<String, Object?> json,
  ) => switch (json['@type']) {
    'inputPageBlockSectionHeading' => InputPageBlockSectionHeading.fromJson(
      json,
    ),
    'inputPageBlockParagraph' => InputPageBlockParagraph.fromJson(json),
    'inputPageBlockPreformatted' => InputPageBlockPreformatted.fromJson(json),
    'inputPageBlockFooter' => InputPageBlockFooter.fromJson(json),
    'inputPageBlockThinking' => InputPageBlockThinking.fromJson(json),
    'inputPageBlockDivider' => InputPageBlockDivider.fromJson(json),
    'inputPageBlockMathematicalExpression' =>
      InputPageBlockMathematicalExpression.fromJson(json),
    'inputPageBlockAnchor' => InputPageBlockAnchor.fromJson(json),
    'inputPageBlockList' => InputPageBlockList.fromJson(json),
    'inputPageBlockBlockQuote' => InputPageBlockBlockQuote.fromJson(json),
    'inputPageBlockExpandableBlockQuote' =>
      InputPageBlockExpandableBlockQuote.fromJson(json),
    'inputPageBlockPullQuote' => InputPageBlockPullQuote.fromJson(json),
    'inputPageBlockAnimation' => InputPageBlockAnimation.fromJson(json),
    'inputPageBlockAudio' => InputPageBlockAudio.fromJson(json),
    'inputPageBlockDocument' => InputPageBlockDocument.fromJson(json),
    'inputPageBlockPhoto' => InputPageBlockPhoto.fromJson(json),
    'inputPageBlockVideo' => InputPageBlockVideo.fromJson(json),
    'inputPageBlockVoiceNote' => InputPageBlockVoiceNote.fromJson(json),
    'inputPageBlockCollage' => InputPageBlockCollage.fromJson(json),
    'inputPageBlockSlideshow' => InputPageBlockSlideshow.fromJson(json),
    'inputPageBlockTable' => InputPageBlockTable.fromJson(json),
    'inputPageBlockDetails' => InputPageBlockDetails.fromJson(json),
    'inputPageBlockMap' => InputPageBlockMap.fromJson(json),
    'inputPageBlockButtonRow' => InputPageBlockButtonRow.fromJson(json),
    final t => throw ArgumentError('unknown InputPageBlock constructor: $t'),
  };
}

