/// Represents a filter for message search results
sealed class SearchMessagesFilter extends TdObject {
  const SearchMessagesFilter();

  static SearchMessagesFilter fromJson(
    Map<String, Object?> json,
  ) => switch (json['@type']) {
    'searchMessagesFilterEmpty' => SearchMessagesFilterEmpty.fromJson(json),
    'searchMessagesFilterAnimation' => SearchMessagesFilterAnimation.fromJson(
      json,
    ),
    'searchMessagesFilterAudio' => SearchMessagesFilterAudio.fromJson(json),
    'searchMessagesFilterDocument' => SearchMessagesFilterDocument.fromJson(
      json,
    ),
    'searchMessagesFilterPhoto' => SearchMessagesFilterPhoto.fromJson(json),
    'searchMessagesFilterPoll' => SearchMessagesFilterPoll.fromJson(json),
    'searchMessagesFilterVideo' => SearchMessagesFilterVideo.fromJson(json),
    'searchMessagesFilterVoiceNote' => SearchMessagesFilterVoiceNote.fromJson(
      json,
    ),
    'searchMessagesFilterPhotoAndVideo' =>
      SearchMessagesFilterPhotoAndVideo.fromJson(json),
    'searchMessagesFilterUrl' => SearchMessagesFilterUrl.fromJson(json),
    'searchMessagesFilterChatPhoto' => SearchMessagesFilterChatPhoto.fromJson(
      json,
    ),
    'searchMessagesFilterVideoNote' => SearchMessagesFilterVideoNote.fromJson(
      json,
    ),
    'searchMessagesFilterVoiceAndVideoNote' =>
      SearchMessagesFilterVoiceAndVideoNote.fromJson(json),
    'searchMessagesFilterMention' => SearchMessagesFilterMention.fromJson(json),
    'searchMessagesFilterUnreadMention' =>
      SearchMessagesFilterUnreadMention.fromJson(json),
    'searchMessagesFilterUnreadReaction' =>
      SearchMessagesFilterUnreadReaction.fromJson(json),
    'searchMessagesFilterUnreadPollVote' =>
      SearchMessagesFilterUnreadPollVote.fromJson(json),
    'searchMessagesFilterFailedToSend' =>
      SearchMessagesFilterFailedToSend.fromJson(json),
    'searchMessagesFilterPinned' => SearchMessagesFilterPinned.fromJson(json),
    final t => throw ArgumentError(
      'unknown SearchMessagesFilter constructor: $t',
    ),
  };
}

