  /// Sticker set thumbnail in WEBP, TGS, or WEBM format with width and height 100; may be null. The file can be downloaded only before the thumbnail is changed
  final Thumbnail? thumbnail;

  /// Sticker set thumbnail's outline; may be null if unknown
  final Outline? thumbnailOutline;

  /// True, if the sticker set is owned by the current user
  final bool isOwned;

  /// True, if the sticker set has been installed by the current user
  final bool isInstalled;

  /// True, if the sticker set has been archived. A sticker set can't be installed and archived simultaneously
  final bool isArchived;

  /// True, if the sticker set is official
  final bool isOfficial;

  /// Type of the stickers in the set
  final StickerType? stickerType;

  /// True, if stickers in the sticker set are custom emoji that must be repainted; for custom emoji sticker sets only
  final bool needsRepainting;

  /// True, if stickers in the sticker set are custom emoji that can be used as chat emoji status; for custom emoji sticker sets only
  final bool isAllowedAsChatEmojiStatus;

  /// True for already viewed trending sticker sets
  final bool isViewed;

  /// List of stickers in this set
  final List<Sticker> stickers;

  /// A list of emojis corresponding to the stickers in the same order. The list is only for informational purposes, because a sticker is always sent with a fixed emoji from the corresponding Sticker object
  final List<Emojis> emojis;

  const StickerSet({
    required this.id,
    required this.title,
    required this.name,
    this.thumbnail,
    this.thumbnailOutline,
    required this.isOwned,
    required this.isInstalled,
    required this.isArchived,
    required this.isOfficial,
    this.stickerType,
    required this.needsRepainting,
    required this.isAllowedAsChatEmojiStatus,
    required this.isViewed,
    required this.stickers,
    required this.emojis,
  });

  static const String constructorType = 'stickerSet';
  @override
  String get tdType => constructorType;

  factory StickerSet.fromJson(Map<String, Object?> json) => StickerSet(
    id: int.parse((json['id'] as String?) ?? '0'),
    title: ((json['title'] as String?) ?? ''),
    name: ((json['name'] as String?) ?? ''),
    thumbnail: json['thumbnail'] == null
        ? null
        : Thumbnail.fromJson(json['thumbnail'] as Map<String, Object?>),
    thumbnailOutline: json['thumbnail_outline'] == null
        ? null
        : Outline.fromJson(json['thumbnail_outline'] as Map<String, Object?>),
    isOwned: ((json['is_owned'] as bool?) ?? false),
    isInstalled: ((json['is_installed'] as bool?) ?? false),
    isArchived: ((json['is_archived'] as bool?) ?? false),
    isOfficial: ((json['is_official'] as bool?) ?? false),
    stickerType: json['sticker_type'] == null
        ? null
        : StickerType.fromJson(json['sticker_type'] as Map<String, Object?>),
    needsRepainting: ((json['needs_repainting'] as bool?) ?? false),
    isAllowedAsChatEmojiStatus:
        ((json['is_allowed_as_chat_emoji_status'] as bool?) ?? false),
    isViewed: ((json['is_viewed'] as bool?) ?? false),
    stickers: ((json['stickers'] as List?) ?? const [])
        .map((e) => Sticker.fromJson(e as Map<String, Object?>))
        .toList(),
    emojis: ((json['emojis'] as List?) ?? const [])
        .map((e) => Emojis.fromJson(e as Map<String, Object?>))
        .toList(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id.toString(),
    'title': title,
    'name': name,
    'thumbnail': thumbnail?.toJson(),
    'thumbnail_outline': thumbnailOutline?.toJson(),
    'is_owned': isOwned,
    'is_installed': isInstalled,
    'is_archived': isArchived,
    'is_official': isOfficial,
    'sticker_type': stickerType?.toJson(),
    'needs_repainting': needsRepainting,
    'is_allowed_as_chat_emoji_status': isAllowedAsChatEmojiStatus,
    'is_viewed': isViewed,
    'stickers': stickers.map((e) => e.toJson()).toList(),
    'emojis': emojis.map((e) => e.toJson()).toList(),
  };
}

