  String get tdType => constructorType;

  factory StoryVideo.fromJson(Map<String, Object?> json) => StoryVideo(
    duration: ((json['duration'] as num?) ?? 0).toDouble(),
    width: ((json['width'] as num?) ?? 0).toInt(),
    height: ((json['height'] as num?) ?? 0).toInt(),
    hasStickers: ((json['has_stickers'] as bool?) ?? false),
    isAnimation: ((json['is_animation'] as bool?) ?? false),
    minithumbnail: json['minithumbnail'] == null
        ? null
        : Minithumbnail.fromJson(json['minithumbnail'] as Map<String, Object?>),
    thumbnail: json['thumbnail'] == null
        ? null
        : Thumbnail.fromJson(json['thumbnail'] as Map<String, Object?>),
    preloadPrefixSize: ((json['preload_prefix_size'] as num?) ?? 0).toInt(),
    coverFrameTimestamp: ((json['cover_frame_timestamp'] as num?) ?? 0)
        .toDouble(),
    video: json['video'] == null
        ? null
        : File.fromJson(json['video'] as Map<String, Object?>),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'duration': duration,
    'width': width,
    'height': height,
    'has_stickers': hasStickers,
    'is_animation': isAnimation,
    'minithumbnail': minithumbnail?.toJson(),
    'thumbnail': thumbnail?.toJson(),
    'preload_prefix_size': preloadPrefixSize,
    'cover_frame_timestamp': coverFrameTimestamp,
    'video': video?.toJson(),
  };
}

