  final int viaBotUserId;

  /// Unique identifier of an album this message belongs to; 0 if none. Only audios, documents, photos and videos can be grouped together in albums
  final int mediaAlbumId;

  /// Content of the message
  final MessageContent? content;

  /// Inline keyboard reply markup for the message; may be null if none
  final ReplyMarkup? replyMarkup;

  const QuickReplyMessage({
    required this.id,
    this.sendingState,
    required this.canBeEdited,
    required this.replyToMessageId,
    required this.viaBotUserId,
    required this.mediaAlbumId,
    this.content,
    this.replyMarkup,
  });

  static const String constructorType = 'quickReplyMessage';
  @override
  String get tdType => constructorType;

  factory QuickReplyMessage.fromJson(Map<String, Object?> json) =>
      QuickReplyMessage(
        id: ((json['id'] as num?) ?? 0).toInt(),
        sendingState: json['sending_state'] == null
            ? null
            : MessageSendingState.fromJson(
                json['sending_state'] as Map<String, Object?>,
              ),
        canBeEdited: ((json['can_be_edited'] as bool?) ?? false),
        replyToMessageId: ((json['reply_to_message_id'] as num?) ?? 0).toInt(),
        viaBotUserId: ((json['via_bot_user_id'] as num?) ?? 0).toInt(),
        mediaAlbumId: int.parse((json['media_album_id'] as String?) ?? '0'),
        content: json['content'] == null
            ? null
            : MessageContent.fromJson(json['content'] as Map<String, Object?>),
        replyMarkup: json['reply_markup'] == null
            ? null
            : ReplyMarkup.fromJson(
                json['reply_markup'] as Map<String, Object?>,
              ),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id,
    'sending_state': sendingState?.toJson(),
    'can_be_edited': canBeEdited,
    'reply_to_message_id': replyToMessageId,
    'via_bot_user_id': viaBotUserId,
    'media_album_id': mediaAlbumId.toString(),
    'content': content?.toJson(),
    'reply_markup': replyMarkup?.toJson(),
  };
}

