/// The call is ready to use
final class CallStateReady extends CallState {
  /// Call protocols supported by the other call participant
  final CallProtocol? protocol;

  /// List of available call servers
  final List<CallServer> servers;

  /// A JSON-encoded call config
  final String config;

  /// Call encryption key
  final String encryptionKey;

  /// Encryption key fingerprint represented as 4 emoji
  final List<String> emojis;

  /// True, if peer-to-peer connection is allowed by users privacy settings
  final bool allowP2p;

  /// True, if the other party supports upgrading of the call to a group call
  final bool isGroupCallSupported;

  /// Custom JSON-encoded call parameters to be passed to tgcalls
  final String customParameters;

  const CallStateReady({
    this.protocol,
    required this.servers,
    required this.config,
    required this.encryptionKey,
    required this.emojis,
    required this.allowP2p,
    required this.isGroupCallSupported,
    required this.customParameters,
  });

  static const String constructorType = 'callStateReady';
  @override
  String get tdType => constructorType;

  factory CallStateReady.fromJson(Map<String, Object?> json) => CallStateReady(
    protocol: json['protocol'] == null
        ? null
        : CallProtocol.fromJson(json['protocol'] as Map<String, Object?>),
    servers: ((json['servers'] as List?) ?? const [])
        .map((e) => CallServer.fromJson(e as Map<String, Object?>))
        .toList(),
    config: ((json['config'] as String?) ?? ''),
    encryptionKey: ((json['encryption_key'] as String?) ?? ''),
    emojis: ((json['emojis'] as List?) ?? const [])
        .map((e) => ((e as String?) ?? ''))
        .toList(),
    allowP2p: ((json['allow_p2p'] as bool?) ?? false),
    isGroupCallSupported: ((json['is_group_call_supported'] as bool?) ?? false),
    customParameters: ((json['custom_parameters'] as String?) ?? ''),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'protocol': protocol?.toJson(),
    'servers': servers.map((e) => e.toJson()).toList(),
    'config': config,
    'encryption_key': encryptionKey,
    'emojis': emojis.map((e) => e).toList(),
    'allow_p2p': allowP2p,
    'is_group_call_supported': isGroupCallSupported,
    'custom_parameters': customParameters,
  };
}

