  String get tdType => constructorType;

  factory GroupCallMessage.fromJson(Map<String, Object?> json) =>
      GroupCallMessage(
        messageId: ((json['message_id'] as num?) ?? 0).toInt(),
        senderId: json['sender_id'] == null
            ? null
            : MessageSender.fromJson(json['sender_id'] as Map<String, Object?>),
        date: ((json['date'] as num?) ?? 0).toInt(),
        text: json['text'] == null
            ? null
            : FormattedText.fromJson(json['text'] as Map<String, Object?>),
        paidMessageStarCount: ((json['paid_message_star_count'] as num?) ?? 0)
            .toInt(),
        isFromOwner: ((json['is_from_owner'] as bool?) ?? false),
        canBeDeleted: ((json['can_be_deleted'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'message_id': messageId,
    'sender_id': senderId?.toJson(),
    'date': date,
    'text': text?.toJson(),
    'paid_message_star_count': paidMessageStarCount,
    'is_from_owner': isFromOwner,
    'can_be_deleted': canBeDeleted,
  };
}

