/// Describes a call
final class Call extends TdObject {
  /// Call identifier, not persistent
  final int id;

  /// Persistent unique call identifier; 0 if isn't assigned yet by the server
  final int uniqueId;

  /// User identifier of the other call participant
  final int userId;

  /// True, if the call is outgoing
  final bool isOutgoing;

  /// True, if the call is a video call
  final bool isVideo;

  /// Call state
  final CallState? state;

  const Call({
    required this.id,
    required this.uniqueId,
    required this.userId,
    required this.isOutgoing,
    required this.isVideo,
    this.state,
  });

  static const String constructorType = 'call';
  @override
  String get tdType => constructorType;

  factory Call.fromJson(Map<String, Object?> json) => Call(
    id: ((json['id'] as num?) ?? 0).toInt(),
    uniqueId: int.parse((json['unique_id'] as String?) ?? '0'),
    userId: ((json['user_id'] as num?) ?? 0).toInt(),
    isOutgoing: ((json['is_outgoing'] as bool?) ?? false),
    isVideo: ((json['is_video'] as bool?) ?? false),
    state: json['state'] == null
        ? null
        : CallState.fromJson(json['state'] as Map<String, Object?>),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id,
    'unique_id': uniqueId.toString(),
    'user_id': userId,
    'is_outgoing': isOutgoing,
    'is_video': isVideo,
    'state': state?.toJson(),
  };
}

