/// Represents a single result of an inline query
sealed class InlineQueryResult extends TdObject {
  const InlineQueryResult();

  static InlineQueryResult fromJson(
    Map<String, Object?> json,
  ) => switch (json['@type']) {
    'inlineQueryResultArticle' => InlineQueryResultArticle.fromJson(json),
    'inlineQueryResultContact' => InlineQueryResultContact.fromJson(json),
    'inlineQueryResultLocation' => InlineQueryResultLocation.fromJson(json),
    'inlineQueryResultVenue' => InlineQueryResultVenue.fromJson(json),
    'inlineQueryResultGame' => InlineQueryResultGame.fromJson(json),
    'inlineQueryResultAnimation' => InlineQueryResultAnimation.fromJson(json),
    'inlineQueryResultAudio' => InlineQueryResultAudio.fromJson(json),
    'inlineQueryResultDocument' => InlineQueryResultDocument.fromJson(json),
    'inlineQueryResultPhoto' => InlineQueryResultPhoto.fromJson(json),
    'inlineQueryResultSticker' => InlineQueryResultSticker.fromJson(json),
    'inlineQueryResultVideo' => InlineQueryResultVideo.fromJson(json),
    'inlineQueryResultVoiceNote' => InlineQueryResultVoiceNote.fromJson(json),
    final t => throw ArgumentError('unknown InlineQueryResult constructor: $t'),
  };
}

