  /// Point in time (Unix timestamp) when the event happened
  final int date;

  /// Identifier of the user or chat who performed the action
  final MessageSender? memberId;

  /// The action
  final ChatEventAction? action;

  const ChatEvent({
    required this.id,
    required this.date,
    this.memberId,
    this.action,
  });

  static const String constructorType = 'chatEvent';
  @override
  String get tdType => constructorType;

  factory ChatEvent.fromJson(Map<String, Object?> json) => ChatEvent(
    id: int.parse((json['id'] as String?) ?? '0'),
    date: ((json['date'] as num?) ?? 0).toInt(),
    memberId: json['member_id'] == null
        ? null
        : MessageSender.fromJson(json['member_id'] as Map<String, Object?>),
    action: json['action'] == null
        ? null
        : ChatEventAction.fromJson(json['action'] as Map<String, Object?>),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'id': id.toString(),
    'date': date,
    'member_id': memberId?.toJson(),
    'action': action?.toJson(),
  };
}

