/// Represents the value of a string in a language pack
sealed class LanguagePackStringValue extends TdObject {
  const LanguagePackStringValue();

  static LanguagePackStringValue fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'languagePackStringValueOrdinary' =>
          LanguagePackStringValueOrdinary.fromJson(json),
        'languagePackStringValuePluralized' =>
          LanguagePackStringValuePluralized.fromJson(json),
        'languagePackStringValueDeleted' =>
          LanguagePackStringValueDeleted.fromJson(json),
        final t => throw ArgumentError(
          'unknown LanguagePackStringValue constructor: $t',
        ),
      };
}

/// An ordinary language pack string
final class LanguagePackStringValueOrdinary extends LanguagePackStringValue {
  /// String value
  final String value;

  const LanguagePackStringValueOrdinary({required this.value});

  static const String constructorType = 'languagePackStringValueOrdinary';
  @override
  String get tdType => constructorType;

  factory LanguagePackStringValueOrdinary.fromJson(Map<String, Object?> json) =>
      LanguagePackStringValueOrdinary(
        value: ((json['value'] as String?) ?? ''),
      );

  @override
  Map<String, Object?> toJson() => {'@type': constructorType, 'value': value};
}

/// A language pack string which has different forms based on the number of some object it mentions. See https://www.unicode.org/cldr/charts/latest/supplemental/language_plural_rules.html for more information
final class LanguagePackStringValuePluralized extends LanguagePackStringValue {
  /// Value for zero objects
  final String zeroValue;

  /// Value for one object
  final String oneValue;

  /// Value for two objects
  final String twoValue;

  /// Value for few objects
  final String fewValue;

  /// Value for many objects
  final String manyValue;

  /// Default value
  final String otherValue;

  const LanguagePackStringValuePluralized({
    required this.zeroValue,
    required this.oneValue,
    required this.twoValue,
    required this.fewValue,
    required this.manyValue,
    required this.otherValue,
  });

  static const String constructorType = 'languagePackStringValuePluralized';
  @override
  String get tdType => constructorType;

  factory LanguagePackStringValuePluralized.fromJson(
    Map<String, Object?> json,
  ) => LanguagePackStringValuePluralized(
    zeroValue: ((json['zero_value'] as String?) ?? ''),
    oneValue: ((json['one_value'] as String?) ?? ''),
    twoValue: ((json['two_value'] as String?) ?? ''),
    fewValue: ((json['few_value'] as String?) ?? ''),
    manyValue: ((json['many_value'] as String?) ?? ''),
    otherValue: ((json['other_value'] as String?) ?? ''),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'zero_value': zeroValue,
    'one_value': oneValue,
    'two_value': twoValue,
    'few_value': fewValue,
    'many_value': manyValue,
    'other_value': otherValue,
  };
}

/// A deleted language pack string, the value must be taken from the built-in English language pack
final class LanguagePackStringValueDeleted extends LanguagePackStringValue {
  const LanguagePackStringValueDeleted();

  static const String constructorType = 'languagePackStringValueDeleted';
  @override
  String get tdType => constructorType;

  factory LanguagePackStringValueDeleted.fromJson(Map<String, Object?> json) =>
      LanguagePackStringValueDeleted();

  @override
  Map<String, Object?> toJson() => {'@type': constructorType};
}

/// Represents one language pack string
final class LanguagePackString extends TdObject {
  /// String key
  final String key;

  /// String value; pass null if the string needs to be taken from the built-in English language pack
  final LanguagePackStringValue? value;

  const LanguagePackString({required this.key, this.value});

  static const String constructorType = 'languagePackString';
  @override
  String get tdType => constructorType;

  factory LanguagePackString.fromJson(Map<String, Object?> json) =>
      LanguagePackString(
        key: ((json['key'] as String?) ?? ''),
        value: json['value'] == null
            ? null
            : LanguagePackStringValue.fromJson(
                json['value'] as Map<String, Object?>,
              ),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'key': key,
    'value': value?.toJson(),
  };
}

