/// Describes a feature available to Business user accounts
sealed class BusinessFeature extends TdObject {
  const BusinessFeature();

  static BusinessFeature fromJson(
    Map<String, Object?> json,
  ) => switch (json['@type']) {
    'businessFeatureLocation' => BusinessFeatureLocation.fromJson(json),
    'businessFeatureOpeningHours' => BusinessFeatureOpeningHours.fromJson(json),
    'businessFeatureQuickReplies' => BusinessFeatureQuickReplies.fromJson(json),
    'businessFeatureGreetingMessage' => BusinessFeatureGreetingMessage.fromJson(
      json,
    ),
    'businessFeatureAwayMessage' => BusinessFeatureAwayMessage.fromJson(json),
    'businessFeatureAccountLinks' => BusinessFeatureAccountLinks.fromJson(json),
    'businessFeatureStartPage' => BusinessFeatureStartPage.fromJson(json),
    'businessFeatureBots' => BusinessFeatureBots.fromJson(json),
    'businessFeatureEmojiStatus' => BusinessFeatureEmojiStatus.fromJson(json),
    'businessFeatureChatFolderTags' => BusinessFeatureChatFolderTags.fromJson(
      json,
    ),
    'businessFeatureUpgradedStories' => BusinessFeatureUpgradedStories.fromJson(
      json,
    ),
    final t => throw ArgumentError('unknown BusinessFeature constructor: $t'),
  };
}

