/// Contains information about a limit, increased for Premium users
final class PremiumLimit extends TdObject {
  /// The type of the limit
  final PremiumLimitType? type;

  /// Default value of the limit
  final int defaultValue;

  /// Value of the limit for Premium users
  final int premiumValue;

  const PremiumLimit({
    this.type,
    required this.defaultValue,
    required this.premiumValue,
  });

  static const String constructorType = 'premiumLimit';
  @override
  String get tdType => constructorType;

  factory PremiumLimit.fromJson(Map<String, Object?> json) => PremiumLimit(
    type: json['type'] == null
        ? null
        : PremiumLimitType.fromJson(json['type'] as Map<String, Object?>),
    defaultValue: ((json['default_value'] as num?) ?? 0).toInt(),
    premiumValue: ((json['premium_value'] as num?) ?? 0).toInt(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'type': type?.toJson(),
    'default_value': defaultValue,
    'premium_value': premiumValue,
  };
}

/// Contains information about features, available to Premium users
final class PremiumFeatures extends TdObject {
  /// The list of available features
  final List<PremiumFeature> features;

  /// The list of limits, increased for Premium users
  final List<PremiumLimit> limits;

  /// An internal link to be opened to pay for Telegram Premium if store payment isn't possible; may be null if direct payment isn't available
  final InternalLinkType? paymentLink;

  const PremiumFeatures({
    required this.features,
    required this.limits,
    this.paymentLink,
  });

  static const String constructorType = 'premiumFeatures';
  @override
  String get tdType => constructorType;

  factory PremiumFeatures.fromJson(Map<String, Object?> json) =>
      PremiumFeatures(
        features: ((json['features'] as List?) ?? const [])
            .map((e) => PremiumFeature.fromJson(e as Map<String, Object?>))
            .toList(),
        limits: ((json['limits'] as List?) ?? const [])
            .map((e) => PremiumLimit.fromJson(e as Map<String, Object?>))
            .toList(),
        paymentLink: json['payment_link'] == null
            ? null
            : InternalLinkType.fromJson(
                json['payment_link'] as Map<String, Object?>,
              ),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'features': features.map((e) => e.toJson()).toList(),
    'limits': limits.map((e) => e.toJson()).toList(),
    'payment_link': paymentLink?.toJson(),
  };
}

