/// Contains information about a link to a message or a forum topic in a chat
final class MessageLinkInfo extends TdObject {
  /// True, if the link is a public link for a message or a forum topic in a chat
  final bool isPublic;

  /// If found, identifier of the chat to which the link points, 0 otherwise
  final int chatId;

  /// Identifier of the specific topic in which the message must be opened, or a topic to open if the message is missing; may be null if none
  final MessageTopic? topicId;

  /// If found, the linked message; may be null
  final Message? message;

  /// Timestamp from which the video/audio/video note/voice note/story playing must start, in seconds; 0 if not specified. The media can be in the message content or in its link preview
  final int mediaTimestamp;

  /// Identifier of the checklist task that is linked; 0 if none
  final int checklistTaskId;

  /// Identifier of the poll option that is linked; empty if none
  final String pollOptionId;

  /// True, if the whole media album to which the message belongs is linked
  final bool forAlbum;

  const MessageLinkInfo({
    required this.isPublic,
    required this.chatId,
    this.topicId,
    this.message,
    required this.mediaTimestamp,
    required this.checklistTaskId,
    required this.pollOptionId,
    required this.forAlbum,
  });

  static const String constructorType = 'messageLinkInfo';
  @override
  String get tdType => constructorType;

  factory MessageLinkInfo.fromJson(Map<String, Object?> json) =>
      MessageLinkInfo(
        isPublic: ((json['is_public'] as bool?) ?? false),
        chatId: ((json['chat_id'] as num?) ?? 0).toInt(),
        topicId: json['topic_id'] == null
            ? null
            : MessageTopic.fromJson(json['topic_id'] as Map<String, Object?>),
        message: json['message'] == null
            ? null
            : Message.fromJson(json['message'] as Map<String, Object?>),
        mediaTimestamp: ((json['media_timestamp'] as num?) ?? 0).toInt(),
        checklistTaskId: ((json['checklist_task_id'] as num?) ?? 0).toInt(),
        pollOptionId: ((json['poll_option_id'] as String?) ?? ''),
        forAlbum: ((json['for_album'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'is_public': isPublic,
    'chat_id': chatId,
    'topic_id': topicId?.toJson(),
    'message': message?.toJson(),
    'media_timestamp': mediaTimestamp,
    'checklist_task_id': checklistTaskId,
    'poll_option_id': pollOptionId,
    'for_album': forAlbum,
  };
}

