/// Represents the type of file
sealed class FileType extends TdObject {
  const FileType();

  static FileType fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'fileTypeNone' => FileTypeNone.fromJson(json),
        'fileTypeAnimation' => FileTypeAnimation.fromJson(json),
        'fileTypeAudio' => FileTypeAudio.fromJson(json),
        'fileTypeDocument' => FileTypeDocument.fromJson(json),
        'fileTypeLivePhotoVideo' => FileTypeLivePhotoVideo.fromJson(json),
        'fileTypeNotificationSound' => FileTypeNotificationSound.fromJson(json),
        'fileTypePhoto' => FileTypePhoto.fromJson(json),
        'fileTypePhotoStory' => FileTypePhotoStory.fromJson(json),
        'fileTypeProfilePhoto' => FileTypeProfilePhoto.fromJson(json),
        'fileTypeSecret' => FileTypeSecret.fromJson(json),
        'fileTypeSecretThumbnail' => FileTypeSecretThumbnail.fromJson(json),
        'fileTypeSecure' => FileTypeSecure.fromJson(json),
        'fileTypeSelfDestructingLivePhotoVideo' =>
          FileTypeSelfDestructingLivePhotoVideo.fromJson(json),
        'fileTypeSelfDestructingPhoto' => FileTypeSelfDestructingPhoto.fromJson(
          json,
        ),
        'fileTypeSelfDestructingVideo' => FileTypeSelfDestructingVideo.fromJson(
          json,
        ),
        'fileTypeSelfDestructingVideoNote' =>
          FileTypeSelfDestructingVideoNote.fromJson(json),
        'fileTypeSelfDestructingVoiceNote' =>
          FileTypeSelfDestructingVoiceNote.fromJson(json),
        'fileTypeSticker' => FileTypeSticker.fromJson(json),
        'fileTypeThumbnail' => FileTypeThumbnail.fromJson(json),
        'fileTypeUnknown' => FileTypeUnknown.fromJson(json),
        'fileTypeVideo' => FileTypeVideo.fromJson(json),
        'fileTypeVideoNote' => FileTypeVideoNote.fromJson(json),
        'fileTypeVideoStory' => FileTypeVideoStory.fromJson(json),
        'fileTypeVoiceNote' => FileTypeVoiceNote.fromJson(json),
        'fileTypeWallpaper' => FileTypeWallpaper.fromJson(json),
        final t => throw ArgumentError('unknown FileType constructor: $t'),
      };
}

