/// Contains information about revenue earned from sponsored messages in a chat
final class ChatRevenueAmount extends TdObject {
  /// Cryptocurrency in which revenue is calculated
  final String cryptocurrency;

  /// Total amount of the cryptocurrency earned, in the smallest units of the cryptocurrency
  final int totalAmount;

  /// Amount of the cryptocurrency that isn't withdrawn yet, in the smallest units of the cryptocurrency
  final int balanceAmount;

  /// Amount of the cryptocurrency available for withdrawal, in the smallest units of the cryptocurrency
  final int availableAmount;

  /// True, if Telegram Stars can be withdrawn now or later
  final bool withdrawalEnabled;

  const ChatRevenueAmount({
    required this.cryptocurrency,
    required this.totalAmount,
    required this.balanceAmount,
    required this.availableAmount,
    required this.withdrawalEnabled,
  });

  static const String constructorType = 'chatRevenueAmount';
  @override
  String get tdType => constructorType;

  factory ChatRevenueAmount.fromJson(Map<String, Object?> json) =>
      ChatRevenueAmount(
        cryptocurrency: ((json['cryptocurrency'] as String?) ?? ''),
        totalAmount: int.parse((json['total_amount'] as String?) ?? '0'),
        balanceAmount: int.parse((json['balance_amount'] as String?) ?? '0'),
        availableAmount: int.parse(
          (json['available_amount'] as String?) ?? '0',
        ),
        withdrawalEnabled: ((json['withdrawal_enabled'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'cryptocurrency': cryptocurrency,
    'total_amount': totalAmount.toString(),
    'balance_amount': balanceAmount.toString(),
    'available_amount': availableAmount.toString(),
    'withdrawal_enabled': withdrawalEnabled,
  };
}

