/// Describes state of a revenue withdrawal
sealed class RevenueWithdrawalState extends TdObject {
  const RevenueWithdrawalState();

  static RevenueWithdrawalState fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'revenueWithdrawalStatePending' =>
          RevenueWithdrawalStatePending.fromJson(json),
        'revenueWithdrawalStateSucceeded' =>
          RevenueWithdrawalStateSucceeded.fromJson(json),
        'revenueWithdrawalStateFailed' => RevenueWithdrawalStateFailed.fromJson(
          json,
        ),
        final t => throw ArgumentError(
          'unknown RevenueWithdrawalState constructor: $t',
        ),
      };
}

