      UpdateMessageSendAcknowledged(
        chatId: ((json['chat_id'] as num?) ?? 0).toInt(),
        messageId: ((json['message_id'] as num?) ?? 0).toInt(),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'chat_id': chatId,
    'message_id': messageId,
  };
}

/// A message has been successfully sent
final class UpdateMessageSendSucceeded extends Update {
  /// The sent message. Almost any field of the new message can be different from the corresponding field of the original message. For example, the field scheduling_state may change, making the message scheduled, or non-scheduled
  final Message? message;

  /// The previous temporary message identifier
  final int oldMessageId;

  const UpdateMessageSendSucceeded({this.message, required this.oldMessageId});

  static const String constructorType = 'updateMessageSendSucceeded';
  @override
  String get tdType => constructorType;

  factory UpdateMessageSendSucceeded.fromJson(Map<String, Object?> json) =>
      UpdateMessageSendSucceeded(
        message: json['message'] == null
            ? null
            : Message.fromJson(json['message'] as Map<String, Object?>),
        oldMessageId: ((json['old_message_id'] as num?) ?? 0).toInt(),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'message': message?.toJson(),
    'old_message_id': oldMessageId,
  };
}

