/// Describes a stream to which TDLib internal log is written
sealed class LogStream extends TdObject {
  const LogStream();

  static LogStream fromJson(Map<String, Object?> json) =>
      switch (json['@type']) {
        'logStreamDefault' => LogStreamDefault.fromJson(json),
        'logStreamFile' => LogStreamFile.fromJson(json),
        'logStreamEmpty' => LogStreamEmpty.fromJson(json),
        final t => throw ArgumentError('unknown LogStream constructor: $t'),
      };
}

