  @override
  String get tdType => constructorType;

  factory PostStory.fromJson(Map<String, Object?> json) => PostStory(
    chatId: ((json['chat_id'] as num?) ?? 0).toInt(),
    content: json['content'] == null
        ? null
        : InputStoryContent.fromJson(json['content'] as Map<String, Object?>),
    areas: json['areas'] == null
        ? null
        : InputStoryAreas.fromJson(json['areas'] as Map<String, Object?>),
    caption: json['caption'] == null
        ? null
        : FormattedText.fromJson(json['caption'] as Map<String, Object?>),
    privacySettings: json['privacy_settings'] == null
        ? null
        : StoryPrivacySettings.fromJson(
            json['privacy_settings'] as Map<String, Object?>,
          ),
    albumIds: ((json['album_ids'] as List?) ?? const [])
        .map((e) => ((e as num?) ?? 0).toInt())
