/// Downloads a file from the cloud. Download progress and completion of the download will be notified through updateFile updates
final class DownloadFile extends TdFunction<File> {
  /// Identifier of the file to download
  final int fileId;

  /// Priority of the download (1-32). The higher the priority, the earlier the file will be downloaded. If the priorities of two files are equal, then the last one for which downloadFile/addFileToDownloads was called will be downloaded first
  final int priority;

  /// The starting position from which the file needs to be downloaded
  final int offset;

  /// Number of bytes which need to be downloaded starting from the "offset" position before the download will automatically be canceled; use 0 to download without a limit
  final int limit;

  /// Pass true to return response only after the file download has succeeded, has failed, has been canceled, or a new downloadFile request with different offset/limit parameters was sent; pass false to return file state immediately, just after the download has been started
  final bool synchronous;

  const DownloadFile({
    required this.fileId,
    required this.priority,
    required this.offset,
    required this.limit,
    required this.synchronous,
  });

  static const String constructorType = 'downloadFile';
  @override
  String get tdType => constructorType;

  factory DownloadFile.fromJson(Map<String, Object?> json) => DownloadFile(
    fileId: ((json['file_id'] as num?) ?? 0).toInt(),
    priority: ((json['priority'] as num?) ?? 0).toInt(),
    offset: ((json['offset'] as num?) ?? 0).toInt(),
    limit: ((json['limit'] as num?) ?? 0).toInt(),
    synchronous: ((json['synchronous'] as bool?) ?? false),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'file_id': fileId,
    'priority': priority,
    'offset': offset,
    'limit': limit,
    'synchronous': synchronous,
  };

  @override
  File decodeResult(Map<String, Object?> json) => File.fromJson(json);
}

