/// Imports messages exported from another application
final class ImportMessages extends TdFunction<Ok> {
  /// Identifier of a chat to which the messages will be imported. It must be an identifier of a private chat with a mutual contact or an identifier of a supergroup chat with can_change_info member right
  final int chatId;

  /// File with messages to import. Only inputFileLocal and inputFileGenerated are supported. The file must not be previously uploaded
  final InputFile? messageFile;

  /// Files used in the imported messages. Only inputFileLocal and inputFileGenerated are supported. The files must not be previously uploaded
  final List<InputFile> attachedFiles;

  const ImportMessages({
    required this.chatId,
    this.messageFile,
    required this.attachedFiles,
  });

  static const String constructorType = 'importMessages';
  @override
  String get tdType => constructorType;

  factory ImportMessages.fromJson(Map<String, Object?> json) => ImportMessages(
    chatId: ((json['chat_id'] as num?) ?? 0).toInt(),
    messageFile: json['message_file'] == null
        ? null
        : InputFile.fromJson(json['message_file'] as Map<String, Object?>),
    attachedFiles: ((json['attached_files'] as List?) ?? const [])
        .map((e) => InputFile.fromJson(e as Map<String, Object?>))
        .toList(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'chat_id': chatId,
    'message_file': messageFile?.toJson(),
    'attached_files': attachedFiles.map((e) => e.toJson()).toList(),
  };

  @override
  Ok decodeResult(Map<String, Object?> json) => Ok.fromJson(json);
}

