  factory CreateChatInviteLink.fromJson(Map<String, Object?> json) =>
      CreateChatInviteLink(
        chatId: ((json['chat_id'] as num?) ?? 0).toInt(),
        name: ((json['name'] as String?) ?? ''),
        expirationDate: ((json['expiration_date'] as num?) ?? 0).toInt(),
        memberLimit: ((json['member_limit'] as num?) ?? 0).toInt(),
        createsJoinRequest: ((json['creates_join_request'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'chat_id': chatId,
    'name': name,
    'expiration_date': expirationDate,
    'member_limit': memberLimit,
    'creates_join_request': createsJoinRequest,
  };

  @override
  ChatInviteLink decodeResult(Map<String, Object?> json) =>
      ChatInviteLink.fromJson(json);
}

