/// Sends a code to the specified phone number. Aborts previous phone number verification if there was one. On success, returns information about the sent code
final class SendPhoneNumberCode extends TdFunction<AuthenticationCodeInfo> {
  /// The phone number, in international format
  final String phoneNumber;

  /// Settings for the authentication of the user's phone number; pass null to use default settings
  final PhoneNumberAuthenticationSettings? settings;

  /// Type of the request for which the code is sent
  final PhoneNumberCodeType? type;

  const SendPhoneNumberCode({
    required this.phoneNumber,
    this.settings,
    this.type,
  });

  static const String constructorType = 'sendPhoneNumberCode';
  @override
  String get tdType => constructorType;

  factory SendPhoneNumberCode.fromJson(Map<String, Object?> json) =>
      SendPhoneNumberCode(
        phoneNumber: ((json['phone_number'] as String?) ?? ''),
        settings: json['settings'] == null
            ? null
            : PhoneNumberAuthenticationSettings.fromJson(
                json['settings'] as Map<String, Object?>,
              ),
        type: json['type'] == null
            ? null
            : PhoneNumberCodeType.fromJson(
                json['type'] as Map<String, Object?>,
              ),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'phone_number': phoneNumber,
    'settings': settings?.toJson(),
    'type': type?.toJson(),
  };

  @override
  AuthenticationCodeInfo decodeResult(Map<String, Object?> json) =>
      AuthenticationCodeInfo.fromJson(json);
}

