/// Sets the list of commands supported by the bot for the given user scope and language; for bots only
final class SetCommands extends TdFunction<Ok> {
  /// The scope to which the commands are relevant; pass null to change commands in the default bot command scope
  final BotCommandScope? scope;

  /// A two-letter ISO 639-1 language code. If empty, the commands will be applied to all users from the given scope, for which language there are no dedicated commands
  final String languageCode;

  /// List of the bot's commands
  final List<BotCommand> commands;

  const SetCommands({
    this.scope,
    required this.languageCode,
    required this.commands,
  });

  static const String constructorType = 'setCommands';
  @override
  String get tdType => constructorType;

  factory SetCommands.fromJson(Map<String, Object?> json) => SetCommands(
    scope: json['scope'] == null
        ? null
        : BotCommandScope.fromJson(json['scope'] as Map<String, Object?>),
    languageCode: ((json['language_code'] as String?) ?? ''),
    commands: ((json['commands'] as List?) ?? const [])
        .map((e) => BotCommand.fromJson(e as Map<String, Object?>))
        .toList(),
  );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'scope': scope?.toJson(),
    'language_code': languageCode,
    'commands': commands.map((e) => e.toJson()).toList(),
  };

  @override
  Ok decodeResult(Map<String, Object?> json) => Ok.fromJson(json);
}

