  /// Identifier of the regular gift that will be used for crafting
  final int regularGiftId;

  /// Offset of the first entry to return as received from the previous request; use empty string to get the first chunk of results
  final String offset;

  /// The maximum number of gifts to be returned; must be positive and can't be greater than 100. For optimal performance, the number of returned objects is chosen by TDLib and can be smaller than the specified limit
  final int limit;

  const GetGiftsForCrafting({
    required this.regularGiftId,
    required this.offset,
    required this.limit,
  });

  static const String constructorType = 'getGiftsForCrafting';
  @override
  String get tdType => constructorType;

  factory GetGiftsForCrafting.fromJson(Map<String, Object?> json) =>
      GetGiftsForCrafting(
        regularGiftId: int.parse((json['regular_gift_id'] as String?) ?? '0'),
        offset: ((json['offset'] as String?) ?? ''),
        limit: ((json['limit'] as num?) ?? 0).toInt(),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'regular_gift_id': regularGiftId.toString(),
    'offset': offset,
    'limit': limit,
  };

  @override
  GiftsForCrafting decodeResult(Map<String, Object?> json) =>
      GiftsForCrafting.fromJson(json);
}

