  /// Information about the language pack. Language pack identifier must start with 'X', consist only of English letters, digits and hyphens, and must not exceed 64 characters. Can be called before authorization
  final LanguagePackInfo? info;

  /// Strings of the new language pack
  final List<LanguagePackString> strings;

  const SetCustomLanguagePack({this.info, required this.strings});

  static const String constructorType = 'setCustomLanguagePack';
  @override
  String get tdType => constructorType;

  factory SetCustomLanguagePack.fromJson(Map<String, Object?> json) =>
      SetCustomLanguagePack(
        info: json['info'] == null
            ? null
            : LanguagePackInfo.fromJson(json['info'] as Map<String, Object?>),
        strings: ((json['strings'] as List?) ?? const [])
            .map((e) => LanguagePackString.fromJson(e as Map<String, Object?>))
            .toList(),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'info': info?.toJson(),
    'strings': strings.map((e) => e.toJson()).toList(),
  };

  @override
  Ok decodeResult(Map<String, Object?> json) => Ok.fromJson(json);
}

