/// Optimizes storage usage, i.e. deletes some files and returns new storage usage statistics. Secret thumbnails can't be deleted
final class OptimizeStorage extends TdFunction<StorageStatistics> {
  /// Limit on the total size of files after deletion, in bytes. Pass -1 to use the default limit
  final int size;

  /// Limit on the time that has passed since the last time a file was accessed (or creation time for some filesystems). Pass -1 to use the default limit
  final int ttl;

  /// Limit on the total number of files after deletion. Pass -1 to use the default limit
  final int count;

  /// The amount of time after the creation of a file during which it can't be deleted, in seconds. Pass -1 to use the default value
  final int immunityDelay;

  /// If non-empty, only files with the given types are considered. By default, all types except thumbnails, profile photos, stickers and wallpapers are deleted
  final List<FileType> fileTypes;

  /// If non-empty, only files from the given chats are considered. Use 0 as chat identifier to delete files not belonging to any chat (e.g., profile photos)
  final List<int> chatIds;

  /// If non-empty, files from the given chats are excluded. Use 0 as chat identifier to exclude all files not belonging to any chat (e.g., profile photos)
  final List<int> excludeChatIds;

  /// Pass true if statistics about the files that were deleted must be returned instead of the whole storage usage statistics. Affects only returned statistics
  final bool returnDeletedFileStatistics;

  /// Same as in getStorageStatistics. Affects only returned statistics
  final int chatLimit;

  const OptimizeStorage({
    required this.size,
    required this.ttl,
    required this.count,
    required this.immunityDelay,
    required this.fileTypes,
    required this.chatIds,
    required this.excludeChatIds,
    required this.returnDeletedFileStatistics,
    required this.chatLimit,
  });

  static const String constructorType = 'optimizeStorage';
  @override
  String get tdType => constructorType;

  factory OptimizeStorage.fromJson(Map<String, Object?> json) =>
      OptimizeStorage(
