  final List<String> strings;

  /// Query to search for
  final String query;

  /// The maximum number of objects to return
  final int limit;

  /// Pass true to receive no results for an empty query
  final bool returnNoneForEmptyQuery;

  const SearchStringsByPrefix({
    required this.strings,
    required this.query,
    required this.limit,
    required this.returnNoneForEmptyQuery,
  });

  static const String constructorType = 'searchStringsByPrefix';
  @override
  String get tdType => constructorType;

  factory SearchStringsByPrefix.fromJson(Map<String, Object?> json) =>
      SearchStringsByPrefix(
        strings: ((json['strings'] as List?) ?? const [])
            .map((e) => ((e as String?) ?? ''))
            .toList(),
        query: ((json['query'] as String?) ?? ''),
        limit: ((json['limit'] as num?) ?? 0).toInt(),
        returnNoneForEmptyQuery:
            ((json['return_none_for_empty_query'] as bool?) ?? false),
      );

  @override
  Map<String, Object?> toJson() => {
    '@type': constructorType,
    'strings': strings.map((e) => e).toList(),
    'query': query,
    'limit': limit,
    'return_none_for_empty_query': returnNoneForEmptyQuery,
  };

  @override
  FoundPositions decodeResult(Map<String, Object?> json) =>
      FoundPositions.fromJson(json);
}

